                'teams_setup_title' => 'Office 365-এ বট তৈরি করুন (প্রতি টেন্যান্টে একবার)',
                'teams_step1' => 'Azure portal → Microsoft Entra ID → App registrations → New registration। "Single tenant" বেছে নিন, redirect URI দেবেন না। Application (client) ID নিচের "Bot App ID"-তে এবং Directory (tenant) ID নিচের "Tenant ID"-তে কপি করুন।',
                'teams_step2' => 'Certificates & secrets → New client secret। সিক্রেটের Value (ID নয়) "App secret"-এ কপি করুন। Azure এটি শুধু একবারই দেখায়।',
                'teams_step3' => 'একটি Azure Bot রিসোর্স তৈরি করুন: Single Tenant, বিদ্যমান অ্যাপটি (একই App ID) ব্যবহার করুন। এর Messaging endpoint-এ চ্যানেল তালিকার ওয়েবহুক URL দিন এবং Microsoft Teams চ্যানেল চালু করুন।',
                'teams_step4' => 'botId = App ID দিয়ে একটি Teams অ্যাপ manifest.json প্যাকেজ করুন এবং Teams Admin Center → Manage apps-এ আপলোড করুন। যারা বটের সাথে চ্যাট করবেন তাদের জন্য এটি অনুমোদন করুন।',
                'teams_step5' => 'পারমিশন: কোনোটি নয়। Microsoft Graph পারমিশন যোগ করবেন না। FreeITSM শুধু Bot Framework ব্যবহার করে।',
