        'intros' => [
            'custom_fields' => 'একটি ধরনের টিকিটের জন্য প্রয়োজনীয় অতিরিক্ত তথ্য তৈরি করুন - যেমন নতুন কর্মীর শুরুর তারিখ ও ইউজারনেম - এবং বেছে নিন প্রতিটি কোন টিকিটের প্রকারে থাকবে। প্রতিটি ফিল্ড নিজেই ঠিক করে টিকিট লগ করার সময়, বন্ধ করার সময়, নাকি দুই সময়েই এটি পূরণ করা আবশ্যক, এবং পোর্টালে অনুরোধকারীকে এটি জিজ্ঞাসা করা হবে কি না।',
            'checklists' => 'একটি চেকলিস্ট কিছু স্টেপকে আবশ্যক হিসেবে চিহ্নিত করতে পারে। সেগুলো টিক হওয়ার আগে কেউ টিকিট বন্ধ করলে কী হবে তা এখানে ঠিক করা হয়।',
            'mandatory_fields' => 'টিকিট বন্ধ করার আগে কোন টিকিট ফিল্ডগুলো পূরণ করা আবশ্যক এবং সেগুলোর কোনোটি খালি রেখে কেউ বন্ধ করলে কী হবে তা বেছে নিন। টিকিট যেখানেই বন্ধ করা যায় সেখানেই নিয়মটি প্রযোজ্য: টিকিট স্ক্রিন, বাল্ক অ্যাকশন, REST API এবং ওয়ার্কফ্লো।',
            'departments' => 'বিভাগ টিকিটকে গ্রুপ করে এবং আপনার প্রতিষ্ঠানের সঠিক ক্ষেত্রে পাঠায় — আপনার সার্ভিস ডেস্ক কাজ শ্রেণিবদ্ধ ও বরাদ্দ করতে যেগুলো ব্যবহার করে সেগুলো তৈরি করুন।',
            'teams' => 'দল ঠিক করে বিশ্লেষকেরা কোন বিভাগে প্রবেশ করতে পারবেন। দলে বিভাগ বরাদ্দ করুন, তারপর অ্যাক্সেস নিয়ন্ত্রণ করতে বিশ্লেষকদের দলে বরাদ্দ করুন।',
            'ticket_types' => 'টিকিটের প্রকার ঠিক করে অনুরোধটি কী ধরনের (যেমন ইনসিডেন্ট, সার্ভিস রিকোয়েস্ট) — বিশ্লেষকেরা টিকিটে যেসব প্রকার সেট করতে পারবেন সেগুলো নির্ধারণ করুন।',
            'ticket_origins' => 'টিকিটের উৎস রেকর্ড করে টিকিটটি কীভাবে এসেছে (যেমন ইমেল, ফোন, পোর্টাল) — বিশ্লেষকেরা যেসব উৎস থেকে বেছে নিতে পারবেন সেগুলো নির্ধারণ করুন।',
            'mailboxes' => 'মেইলবক্স FreeITSM-কে ইমেল অ্যাকাউন্টের সাথে যুক্ত করে, ফলে আসা বার্তা টিকিট হয়ে যায় এবং উত্তর বাইরে যায় — আপনার সার্ভিস ডেস্ক যেগুলো পর্যবেক্ষণ করে সেগুলো যোগ করুন এবং প্রমাণীকরণ করুন।',
            'privacy' => 'একটি টিকিটে শুধু অনুরোধকারীর সাথে আপনার কথোপকথনই থাকে না। কোনো সরবরাহকারীকে ফরোয়ার্ড করলে বা কোনো সহকর্মীকে কপিতে রাখলে সেই বার্তা একই টিকিটে যুক্ত হয় — এবং তাঁদের উত্তরও সেখানেই আসে। সেলফ-সার্ভিস পোর্টালে অনুরোধকারী এর কতটা দেখবেন তা এখানে ঠিক করা হয়।',
            'indexing' => 'অ্যাটাচমেন্টের ভেতরের টেক্সট পড়া হয় যাতে তা অনুসন্ধান করা যায়। Word, Excel, PowerPoint এবং সাধারণ টেক্সট ফাইল আসার মুহূর্তেই FreeITSM নিজে পড়ে। PDF, পুরোনো Office ফাইল এবং স্ক্যান করা নথির জন্য আলাদা একটি ডকুমেন্ট-রিডিং সার্ভিস লাগে — সেটি <strong>সিস্টেম &rarr; ইন্টিগ্রেশন &rarr; Apache Tika</strong>-এর অধীনে সেট আপ করুন — এবং এগুলোতে অনেক বেশি সময় লাগে বলে ব্যাকগ্রাউন্ডে পড়া হয়। এই দুটি সুইচ ঠিক করে ব্যাকগ্রাউন্ডের সেই কাজ কখন হবে।',
            'merge_behaviour' => 'দুটি টিকিট একই বিষয় হলে একজন বিশ্লেষক সেগুলো মার্জ করতে পারেন। এই সেটিংগুলো ঠিক করে এতে আপনার অনুরোধকারীদের কাছে থাকা টিকিট রেফারেন্সের কী হবে এবং কথোপকথনগুলোর কী হবে। এগুলো সবার জন্য প্রযোজ্য — মার্জ গ্রাহক যা দেখেন তা বদলে দেয়, তাই একই মেইলবক্সের দুজন বিশ্লেষক এ বিষয়ে ভিন্ন মত রাখতে পারবেন না।',
            'reply_templates' => 'তৈরি করা উত্তর যা আপনার বিশ্লেষকেরা আবার টাইপ না করে উত্তরে বসাতে পারেন। এগুলো শেয়ার করা টেমপ্লেট যা পুরো দল দেখে — বিশ্লেষকের নিজস্ব ব্যক্তিগত টেমপ্লেট উত্তর উইন্ডো থেকে সংরক্ষিত হয় এবং এখানে তালিকাভুক্ত নয়।',
            'rota_shifts' => 'শিফট হলো কাজের ধরনের টেমপ্লেট (যেমন আর্লি, লেট, অন-কল) যা স্টাফ রোটায় বিশ্লেষকদের বরাদ্দ করা হয় — রোটা তৈরির আগে এখানে সেগুলো নির্ধারণ করুন।',
            'analysts' => 'বিশ্লেষকেরা হলেন সেই স্টাফ যাঁরা লগইন করেন এবং টিকিটে কাজ করেন — তাঁদের যোগ করুন, পাসওয়ার্ড রিসেট করুন, এবং অ্যাক্সেস নিয়ন্ত্রণ করতে দলে বরাদ্দ করুন।',
            'general' => 'সাধারণ সেটিং ঠিক করে টিকিট কীভাবে আচরণ করবে - পুনরায় খোলা, স্নুজ করা এবং বার্তা ও থ্রেড কতক্ষণ দেখানো হবে।',
            'statuses' => 'একটি টিকিট যেসব ওয়ার্কফ্লো অবস্থায় থাকতে পারে। <em>বন্ধ</em> হিসেবে চিহ্নিত স্ট্যাটাস চূড়ান্ত বলে গণ্য হয় — রিপোর্ট, ওয়াচটাওয়ার কাউন্টার এবং অ্যাসাইনের সময় বন্ধের তারিখ-সময় স্বয়ংক্রিয়ভাবে বসাতে ব্যবহৃত হয়। নতুন টিকিটের জন্য ঠিক একটি স্ট্যাটাস ডিফল্ট হয়।',
            'priorities' => 'টিকিটে দেখানো অগ্রাধিকারের স্তর। নতুন টিকিটের জন্য ঠিক একটি অগ্রাধিকার ডিফল্ট হয়।',
            'rota_locations' => 'কোনো নির্দিষ্ট দিনে প্রতিটি বিশ্লেষক কোথায় কাজ করছেন — স্টাফ রোটা ব্যবহার করে এবং প্রতিটি এন্ট্রিতে রঙিন ব্যাজ হিসেবে দেখানো হয়। নতুন রোটা এন্ট্রির জন্য ঠিক একটি স্থান ডিফল্ট হয়।',
            'email_templates' => 'টিকিটের ইভেন্টে চালু হওয়া স্বয়ংক্রিয় ইমেল উত্তর। প্রতিটি ইভেন্টের জন্য শুধু প্রথম সক্রিয় টেমপ্লেটটি ব্যবহৃত হয়।',
        ],
        'messaging' => [
            'channels_heading' => 'মেসেজিং চ্যানেল',
            'channels_intro' => 'গ্রাহকদের WhatsApp-এর মাধ্যমে বিশ্লেষকের সাথে চ্যাট করতে দিন — প্রতিটি বার্তা ইমেলের মতোই একটি টিকিট হয়ে যায়। নিচে একটি চ্যানেল যোগ করুন, তারপর এর <strong>ওয়েবহুক URL</strong> আপনার প্রদানকারীর (Twilio বা Meta) কাছে পেস্ট করুন যাতে ইনবাউন্ড বার্তা এই ইনস্টলে পৌঁছায়।',
            'base_url_label' => '<strong>পাবলিক বেস URL</strong>',
            'base_url_placeholder' => 'https://your-domain.com  (অথবা পরীক্ষার সময় আপনার ngrok ঠিকানা)',
            'base_url_help' => 'প্রদানকারীরা এই ইনস্টলে পৌঁছাতে যে ঠিকানা ব্যবহার করে। এটি সেট করলে নিচের ওয়েবহুক URL-গুলো কপি-পেস্টের জন্য তৈরি হয়ে যায়। ফাঁকা রাখলে আপনি যে ঠিকানা থেকে ব্রাউজ করছেন সেটিই ব্যবহৃত হবে। লোকালি পরীক্ষা করছেন? <code>ngrok http 80</code> চালান এবং এটি যে <code>https://…ngrok-free.dev</code> ঠিকানা দেখায় তা পেস্ট করুন।',
