            'notifs_info' => '<strong style="display:block;margin-bottom:6px;font-size:14px;">নোটিফিকেশন নিয়ম কীভাবে কাজ করে</strong>প্রতিটি নিয়মের চারটি অংশ: একটি <strong>স্কোপ</strong>, একটি <strong>ট্রিগার</strong>, একটি <strong>লক্ষ্য</strong> এবং <strong>প্রাপকদের</strong> তালিকা।<br><br><strong>স্কোপ</strong> হয় <em>ডিফল্ট</em> (নিয়মটি প্রতিটি বিভাগের টিকিটে প্রযোজ্য) অথবা একটি <em>নির্দিষ্ট বিভাগ</em> (নিয়মটি শুধু সেই বিভাগের টিকিটে প্রযোজ্য)।<br>কোনো টিকিট মূল্যায়নের সময় সিস্টেম আগে তার বিভাগের সাথে মেলে এমন নিয়ম খোঁজে &mdash; থাকলে সেই নিয়মই চলে, ডিফল্ট উপেক্ষিত হয়। বিভাগ-নির্দিষ্ট নিয়ম না থাকলে ডিফল্ট নিয়ম ব্যবহার হয়। এভাবে আপনি সব বিভাগের জন্য যুক্তিসংগত ডিফল্ট রেখে, যে টিমের এসক্যালেশন চাহিদা আলাদা সেখানে ব্যতিক্রম করতে পারেন।<br><br><strong>ট্রিগার</strong> হয় <em>সতর্কতা</em> (টিকিট সতর্কতার সীমা পেরিয়েছে &mdash; লঙ্ঘন ঘনিয়ে আসছে) অথবা <em>লঙ্ঘন</em> (টিকিট এখন SLA লক্ষ্য ছাড়িয়ে গেছে &mdash; প্রকৃত লঙ্ঘন)। প্রতিটি আলাদা নিয়ম, তাই সতর্কতা ও লঙ্ঘনে আলাদা মানুষকে জানাতে পারেন।<br><br><strong>লক্ষ্য</strong> হলো কোন SLA ঘড়ি দেখা হবে &mdash; <em>রেসপন্স</em>, <em>রেজোলিউশন</em> অথবা <em>উভয়</em>।<br><br><strong>প্রাপক</strong> নিচের যেকোনো সমন্বয় হতে পারে: টিকিটের বর্তমান নিযুক্ত ব্যক্তি, টিকিটের বিভাগের টিমগুলোর প্রত্যেক বিশ্লেষক, একজন নির্দিষ্ট বিশ্লেষক, এবং/অথবা যেকোনো ইমেল ঠিকানার তালিকা (শেয়ার্ড ইনবক্স বা Slack/Teams ইমেল ব্রিজের জন্য কাজের)।<br><br><strong style="color:var(--warning-text, #92400e);">নিয়ম নেই = ইমেল নেই।</strong> টিকিট লঙ্ঘন করলেও অন্তত একটি নিয়ম না যোগ করা পর্যন্ত কিছুই পাঠানো হবে না (সবকিছুর জন্য কভারেজ পেতে ডিফল্ট-স্কোপের সতর্কতা + লঙ্ঘন জোড়া দিয়ে শুরু করুন)।',
            'notifs_dedup' => 'প্রতিটি টিকিট প্রতিটি লক্ষ্য ও ট্রিগারের জন্য সর্বোচ্চ একটি ইমেল পাঠায় &mdash; cron ওয়ার্কার মনে রাখে কী পাঠানো হয়েছে, তাই ডুপ্লিকেট আসে না।',
