            'notifs_cron_note' => 'এই ইমেলগুলো পাঠানো cron ওয়ার্কারটি আছে <code>cron/sla_breach_check.php</code>-এ। Windows Task Scheduler ও Linux cron সেটআপের জন্য দেখুন <code>docs/sla-cron-setup.md</code>।',
            'cron_heading' => 'Cron কার্যকলাপ',
            'cron_refresh' => 'রিফ্রেশ',
            'cron_intro' => 'লঙ্ঘন-পরীক্ষা cron-এর সর্বশেষ <span id="slaCronRunsLimit">20</span>টি চালানো (CLI ও HTTP)। প্রত্যাখ্যাত অনুরোধও (রেট-লিমিটেড, অথেন্টিকেশন ব্যর্থ) অন্তর্ভুক্ত, যাতে একই তথ্যসূত্র থেকে রেট-লিমিট পরীক্ষা ও নিরাপত্তা অডিট চলে। <strong><span id="slaCronRetentionDays">30</span> দিন</strong> পর স্বয়ংক্রিয়ভাবে মুছে যায়; সফল চালানোর মধ্যে ন্যূনতম ব্যবধান <strong><span id="slaCronMinInterval">30</span> সেকেন্ড</strong> (দুটিই <code>system_settings</code>-এ কনফিগারযোগ্য)।',
