            'scope_help' => 'টিকিটের ধরন অনুযায়ী গুনলে ইনসিডেন্ট ও রিকোয়েস্ট নিজ নিজ নম্বরের সারি পায়, বেশিরভাগ বড় সার্ভিস ডেস্ক এভাবেই করে। আলাদাভাবে গুনলে ফরম্যাটে বলতে হবে কোনটি কোন গোষ্ঠীর — এতে {TYPE} বা {COMPANY} রাখুন, নইলে প্রতিটি গোষ্ঠী একই নম্বর তৈরি করবে।',
