            'reset_help' => 'শুধু তখনই কাজের যখন বছর বা মাস নম্বরের অংশ, নইলে ডুপ্লিকেট হবে। <code>INC-{YYYY}-{#####}</code>-এর মতো কিছুর সাথে মিলিয়ে ব্যবহার করুন।',
            'existing_note' => '<strong>আগে থেকে নম্বর পাওয়া কিছুই বদলাবে না।</strong> বিদ্যমান টিকিট তাদের রেফারেন্স রাখে, আর FreeITSM আজ পর্যন্ত যত রেফারেন্স দিয়েছে সবই কাজ করতে থাকে &mdash; পুরোনো ইমেলের উত্তরেও। বিদ্যমান টিকিটও নতুন করে নম্বর দিতে চাইলে নিচে তার একটি টুল আছে। <strong>অঙ্ক ফুরিয়ে যাবে না:</strong> আপনার বেছে নেওয়া প্রস্থ ন্যূনতম, তাই ১,০০০,০০১ নম্বর টিকিট ভেঙে না গিয়ে শুধু একটি অঙ্ক বেশি পায়।',
