            'intro' => 'টিকিট মডিউল আপনার আইটি সার্ভিস ডেস্কের মূল অংশ। সাপোর্টের অনুরোধ, ইনসিডেন্ট এবং সার্ভিস টাস্ক পরিচালনার জন্য এতে ইমেল ক্লায়েন্টের মতো পরিচিত একটি ইন্টারফেস আছে। এন্ড ইউজারদের কাছ থেকে ইমেলের মাধ্যমে বা হাতে তৈরি হয়ে টিকিট আসে, আর বিশ্লেষকরা ফোল্ডার, অগ্রাধিকার ও SLA টাইমার ব্যবহার করে সেগুলোর কাজ করেন &mdash; দ্রুত আইটি সাপোর্ট দিতে যা যা দরকার সবই এখানে আছে।',
            'card_inbox_title' => 'ইনবক্স',
            'card_inbox_body' => 'ইমেল ক্লায়েন্টের আদলে তৈরি একটি ফোল্ডারভিত্তিক ইনবক্স। আমার টিকিট, অনির্ধারিত, সব খোলা এবং বন্ধ ফোল্ডার দেখুন। যেকোনো টিকিটে ক্লিক করলে রিডিং প্যানে পূর্ণ বিবরণ, ইতিহাস ও অ্যাকশন দেখা যায়।',
            'card_dashboard_title' => 'ড্যাশবোর্ড',
            'card_dashboard_body' => 'কাস্টমাইজ করা যায় এমন Chart.js উইজেট দিয়ে নিজের ড্যাশবোর্ড তৈরি করুন। বার, পাই, ডোনাট ও লাইন চার্টে টিকিটের পরিমাণ, সাড়াদানের সময়, বিভাগভিত্তিক বিভাজন এবং বিশ্লেষকদের কাজের চাপ দেখুন।',
            'card_calendar_title' => 'ক্যালেন্ডার',
            'card_calendar_body' => 'টিকিটের তৈরি, নির্ধারিত বা সমাধানের তারিখ অনুযায়ী ক্যালেন্ডার গ্রিডে সেগুলো দেখুন। বিলম্বিত আইটেম সহজে চোখে পড়ে এবং টিকিটের পুরো চিত্র এক নজরে দেখে সপ্তাহের পরিকল্পনা করা যায়।',
            'card_rota_title' => 'রোটা',
            'card_rota_body' => 'বিশ্লেষকদের শিফট ও অন-কল রোটা সাজান। যেকোনো সময় কে উপলব্ধ তা দেখুন, সপ্তাহান্ত ও ছুটির দিনের কভারেজ পরিকল্পনা করুন এবং নিশ্চিত করুন কোনো টিকিট যেন অবহেলিত না থাকে।',
        ],
        'inbox' => [
            'heading' => 'ইনবক্স',
            'intro' => 'ইনবক্স বিশ্লেষকদের প্রধান কর্মক্ষেত্র। এতে তিনটি প্যানের বিন্যাস আছে &mdash; বাঁয়ে ফোল্ডার, মাঝখানে টিকিটের তালিকা এবং ডানে রিডিং প্যানে &mdash; তাই পেজ ছেড়ে না গিয়েই আপনি টিকিট বাছাই ও উত্তর দিতে পারেন।',
            'p_live' => '<strong>এটি নিজে থেকেই হালনাগাদ থাকে।</strong> প্রতি মিনিটে ইনবক্স আপনার মেইলবক্স পরীক্ষা করে এবং আপনার দেখতে পাওয়া টিকিটে নতুন কিছু এসেছে কি না দেখে &mdash; ব্যাকগ্রাউন্ডে সংগৃহীত ইমেল, WhatsApp, Telegram, Slack, Teams বা Mattermost বার্তা, কোনো সহকর্মীর উত্তর &mdash; আর কিছু এলে রিফ্রেশ বোতাম চাপার মতোই তালিকা ও ফোল্ডারের সংখ্যা নিজে থেকে রিফ্রেশ হয়ে যায়। আপনি যে টিকিটটি পড়ছেন এবং যে উত্তর লিখছেন তাতে হাত দেওয়া হয় না।',
            'p_folders' => 'ফোল্ডার প্যানে টিকিটগুলো যুক্তিসংগত দলে সাজানো থাকে। প্রতিটি ফোল্ডারে অপঠিত সংখ্যা দেখানো হয়, তাই নতুন কাজ সঙ্গে সঙ্গে চোখে পড়ে:',
            'field_my' => '<strong>আমার টিকিট</strong> &mdash; আপনার নামে নির্ধারিত টিকিট। এটি আপনার ব্যক্তিগত সারি এবং প্রতিদিন শুরু করার সেরা জায়গা।',
            'field_unassigned' => '<strong>অনির্ধারিত</strong> &mdash; যেসব টিকিট এসেছে কিন্তু এখনও কোনো বিশ্লেষক পায়নি। দায়িত্ব নিতে এখান থেকে আইটেম বেছে নিন।',
            'field_all_open' => '<strong>সব খোলা</strong> &mdash; মালিক যেই হোন, বন্ধ হয়নি এমন প্রতিটি টিকিট। ম্যানেজার ও টিম লিডদের জন্য সামগ্রিক পরিমাণ নজরে রাখতে কাজের।',
            'field_closed' => '<strong>বন্ধ</strong> &mdash; সমাধান হওয়া টিকিট। আগের কোনো সমাধান দেখতে বা কোনো সমস্যা আবার খুলতে এখানে অনুসন্ধান করুন।',
            'field_dept' => '<strong>বিভাগের ফোল্ডার</strong> &mdash; বিভাগ অনুযায়ী সাজানো টিকিট (যেমন IT, HR, Finance)। বিভাগ সেটিংসে কনফিগার করা হয় এবং সাব-ফোল্ডার হিসেবে নিজে থেকেই দেখা যায়।',
            'switch_heading' => '<strong>বিভাগ ও বিশ্লেষক অনুযায়ী সাজানোর মধ্যে বদল</strong>',
            'switch_body' => 'ফোল্ডার প্যানের উপরে দুই বোতামের একটি ছোট টগল একই ডেটার দুটি ভিউয়ের মধ্যে বদল করে। <strong>বিভাগ</strong> অনুযায়ী সাজানো (ডিফল্ট) প্রতিটি বিভাগের নিচে টিকিট দেখায় এবং ভেতরে স্ট্যাটাসের সাব-ফোল্ডার থাকে; <strong>বিশ্লেষক</strong> অনুযায়ী সাজালে উল্টে যায়, অর্থাৎ প্রতিটি উপরের স্তরের ফোল্ডার একজন বিশ্লেষকের ব্যক্তিগত সারি, ভেতরে স্ট্যাটাসের সাব-ফোল্ডার। <strong>অনির্ধারিত</strong> ফোল্ডার প্রতিটি ভিউয়ে প্রসঙ্গ অনুযায়ী আচরণ করে &mdash; বিভাগ ভিউয়ে এটি বিভাগ ঠিক না করা টিকিট দেখায়; বিশ্লেষক ভিউয়ে এটি কাউকে নিযুক্ত না করা টিকিট দেখায় &mdash; ফলে কোনটি তুলে নেওয়া দরকার তা সবসময় দেখতে পাবেন। আপনার পছন্দ প্রত্যেক বিশ্লেষকের জন্য আলাদাভাবে সংরক্ষিত হয়, তাই প্রতিটি সদস্য সেশনের পর সেশনে নিজের পছন্দের ভিউ পান।',
            'p_actions' => 'টিকিটের তালিকার উপরে চারটি অ্যাকশন বোতাম আছে: টিকিট তৈরি করতে <strong>নতুন</strong>, কীওয়ার্ড, রেফারেন্স বা অনুরোধকারী দিয়ে টিকিট খুঁজতে <strong>অনুসন্ধান</strong>, কী দেখবেন তা সীমিত করতে <strong>ফিল্টার</strong>, আর বর্তমান ফোল্ডার আবার লোড করতে <strong>রিফ্রেশ</strong>।',
            'filter_body' => '<strong>ফিল্টার</strong> বোতাম (ফানেল) যেভাবেই সাজানো থাকুক, ফোল্ডার ও তালিকা দুটিকেই একসাথে সীমিত করে। <strong>আমার</strong> শুধু আপনার নামে নির্ধারিত টিকিট দেখায়, আর <strong>বন্ধ লুকান</strong> যেসব টিকিটের স্ট্যাটাস বন্ধ হিসেবে চিহ্নিত সেগুলো বাদ দেয়। ফিল্টার চালু থাকলে ফানেলে একটি বিন্দু থাকে এবং তালিকার শিরোনামের পাশে একটি লেবেল দেখা যায়, তাই আপনি সবসময় জানেন যে সবকিছু দেখছেন না। ফোল্ডার <strong>বিশ্লেষক</strong> অনুযায়ী সাজানো থাকলে আপনার নিজের ফোল্ডার তার বদলে <strong>আমার টিকিট</strong> নামে সবার উপরে থাকে। অনুসন্ধানের নিজস্ব <strong>বন্ধ টিকিট অন্তর্ভুক্ত করুন</strong> সুইচ আছে, যা ডিফল্টভাবে চালু, কারণ অনুসন্ধান সাধারণত পুরোনো টিকিট খোঁজার জন্যই হয়। দুটি পছন্দই শুধু আপনার জন্য সংরক্ষিত হয়।',
            'row_name' => 'প্রতিটি সারিতে টিকিটের রেফারেন্স এবং তার পর একটি নাম দেখায়। ডিফল্টভাবে এটি <strong>যিনি টিকিটটি তুলেছেন</strong> তার নাম, এবং টিকিটের পুরো জীবনে তা একই থাকে। যদি সাম্প্রতিকতম বার্তার প্রেরককে দেখতে চান &mdash; উত্তর দেওয়ার পর যা আপনার নিজের মেইলবক্স হয়ে যায় &mdash; তাহলে <strong>টিকিট নম্বরের পাশের নাম</strong> সেটিংটি <strong>সেটিংস &rarr; সারির প্রদর্শন</strong>-এর অধীনে বদলান; সেখানে নাম লুকিয়ে শুধু রেফারেন্সও রাখা যায়। ওই ট্যাব আপনার নিজস্ব সেটিং: এতে অন্য কারও কিছু বদলায় না।',
            'tip' => 'তালিকার যেকোনো টিকিটে ক্লিক করলে সেটি রিডিং প্যানে লোড হয়। সেখান থেকে ফিল্ড হালনাগাদ করা, মন্তব্য যোগ করা, ইমেলে উত্তর দেওয়া বা ফাইল সংযুক্ত করা যায় &mdash; ইনবক্স ছেড়ে না গিয়েই।',
        ],
        'faster' => [
            'heading' => 'দ্রুত কাজ করা',
            'intro' => 'ব্যস্ত সকালকে সামলানোর মতো করে তোলে চারটি জিনিস: সংরক্ষিত উত্তর, একসাথে অনেক টিকিটে কাজ করা, এবং কথোপকথনকে তার সঠিক জায়গায় রাখা।',
            'templates_heading' => 'তৈরি উত্তর',
            'templates_body' => 'আপনি বারবার একই কয়েকটি উত্তর পাঠান। একবার লিখে রাখুন, তারপর উত্তর লেখার উইন্ডোর নিচে বাঁয়ে <strong>টেমপ্লেট</strong>-এ ক্লিক করে কার্সারের জায়গায় বসিয়ে দিন &mdash; আগে যা লিখেছেন তা বদলায় না, তার সঙ্গে যোগ হয়। টেমপ্লেট রিচ টেক্সট এবং স্বয়ংক্রিয় ইমেলের মতোই <code>[merge_code]</code> প্লেসহোল্ডার সমর্থন করে, তাই বসানোর সময়ই <code>[requester_first_name]</code> আসল নাম হয়ে যায়।',
            'templates_team' => '<strong>টিমের টেমপ্লেট</strong> &mdash; সবার সঙ্গে শেয়ার করা, সেটিংস &rarr; উত্তরের টেমপ্লেটে তৈরি হয়।',
            'templates_mine' => '<strong>আপনার নিজের</strong> &mdash; <em>খসড়াকে টেমপ্লেট হিসেবে সংরক্ষণ</em> দিয়ে একটি খসড়া সংরক্ষণ করুন। শুধু আপনার জন্য, কোনো অনুমতি লাগে না।',
            'templates_tip' => 'টেমপ্লেটের নাম দিন পরিস্থিতি অনুযায়ী ("প্রিন্টার অফলাইন &mdash; প্রথম স্টেপগুলো"), শব্দ অনুযায়ী নয়। সকাল ৯টায় আপনি ঠিক এটাই খুঁজবেন।',
            'select_heading' => 'একাধিক টিকিট নির্বাচন',
            'select_body' => 'টিকিটের তালিকা Outlook বা File Explorer-এর মতো কাজ করে। কোনো চেকবক্স নেই।',
            'key_click' => 'ক্লিক',
            'key_click_d' => 'একটি নির্বাচন করে খুলুন',
            'key_ctrl' => 'Ctrl+ক্লিক',
            'key_ctrl_d' => 'বাকিগুলো না ছুঁয়ে একটি যোগ বা বাদ দিন',
            'key_shift' => 'Shift+ক্লিক',
