            'select_actions' => 'একাধিক নির্বাচিত থাকলে এগুলোর <strong>যেকোনোটিতে রাইট-ক্লিক করুন</strong> এবং সবগুলোর স্ট্যাটাস, অগ্রাধিকার, বিভাগ, ধরন বা নিযুক্ত ব্যক্তি একসাথে ঠিক করুন &mdash; অথবা পুরো সেটটি একটি ফোল্ডারে টেনে ফেলুন। একাধিক নির্বাচিত থাকলে স্ক্রিনে কী দেখাবে তা আপনার পছন্দ, অ্যাকাউন্ট মেনুর পছন্দসমূহে ঠিক করা যায়।',
