            'merge_heading' => 'ডুপ্লিকেট একত্র করা',
            'merge_body' => 'দুজন একই বিভ্রাটের কথা জানিয়েছেন? টিকিটগুলো নির্বাচন করুন, রাইট-ক্লিক করুন, <strong>মার্জ</strong>। কথোপকথনগুলো এক হয়ে যায়, আর AI প্রোভাইডার কনফিগার করা থাকলে FreeITSM সবাই কী জিজ্ঞাসা করেছেন এবং এ পর্যন্ত কী করা হয়েছে তার একটি সংক্ষিপ্ত বিবরণ লিখে দেয়, যাতে যিনি কাজটি নেবেন তাকে চারটি থ্রেড পড়তে না হয়।',
            'merge_tip' => 'কিছুই কখনো মুছে যায় না। মার্জ হয়ে যাওয়া টিকিট তার রেফারেন্স রাখে, অনুসন্ধানে পাওয়া যায়, কোথায় গেছে তা দেখায় &mdash; এবং কোনো গ্রাহক এ নিয়ে পুরোনো ইমেলে উত্তর দিলে তা এখনও আপনার কাছেই পৌঁছায়।',
            'split_heading' => 'টিকিট ভাগ করা',
            'split_body' => 'উল্টো কাজ। কেউ কথোপকথনের মাঝখানে অন্য একটি সম্পর্কহীন বিষয় তুললে সেই বার্তায় <strong>ভাগ</strong>-এ ক্লিক করুন (অথবা বার্তার হেডারে রাইট-ক্লিক করুন)। এটি একটি নতুন টিকিটে চলে যায়, চাইলে এর পরের সব বার্তাও সঙ্গে নিয়ে, আর মূল টিকিটে একটি চিহ্ন থেকে যায় যা দেখায় সেগুলো কোথায় গেছে।',
            'split_tip' => 'নতুন টিকিটকে একটি সঠিক বিষয় দিন। ডিফল্টে এটি সরানো বার্তার&rsquo; বিষয়ই নেয়, যা সাধারণত <em>পুরোনো</em> সমস্যার একটি "RE:"।',
            'undo_heading' => 'মত বদলালে',
            'undo_body' => 'দুটিই টিকিটের ব্যানার থেকে পূর্বাবস্থায় ফেরানো যায়। নতুন টিকিটে কেউ উত্তর দিলে, নোট যোগ করলে বা সময় লগ করলে <strong>ভাগ</strong> পূর্বাবস্থায় ফেরানো যায় না &mdash; কী বাধা হয়ে আছে তা আপনাকে ঠিকঠাক জানানো হয়। <strong>মার্জ</strong> পূর্বাবস্থায় ফেরালে টিকিট তার বার্তা, নোট ও লগ করা সময় ফিরে পায় এবং ঠিক আগের অবস্থায় আবার খোলে, কিন্তু মার্জের পর অন্য টিকিটে লেখা উত্তরগুলো সেখানেই থেকে যায়।',
