            'step2' => '<strong>বিষয় ঠিক করুন</strong> &mdash; সমস্যার একটি স্পষ্ট, সংক্ষিপ্ত সারাংশ লিখুন। এটি টিকিটের তালিকায় এবং এন্ড ইউজারকে পাঠানো সব ইমেল বিজ্ঞপ্তিতে দেখা যায়।',
            'step3' => '<strong>বিভাগ, ধরন ও অগ্রাধিকার বেছে নিন</strong> &mdash; উপযুক্ত বিভাগ, টিকিটের ধরন (যেমন ইনসিডেন্ট, সার্ভিস রিকোয়েস্ট) এবং অগ্রাধিকারের মাত্রা নির্বাচন করুন। এই ফিল্ডগুলো SLA টাইমার ও রাউটিং নিয়ম চালায়।',
            'step4' => '<strong>বিবরণ যোগ করুন</strong> &mdash; রিচ টেক্সট এডিটরে সমস্যার পূর্ণ বিবরণ দিন। কীভাবে সমস্যাটি ঘটানো যায়, ত্রুটির বার্তা এবং সমাধানকারী বিশ্লেষকের যা যা প্রাসঙ্গিক তথ্য লাগবে তা অন্তর্ভুক্ত করুন।',
            'step5' => '<strong>সংরক্ষণ</strong> &mdash; টিকিটটি একটি অনন্য রেফারেন্স নম্বর নিয়ে তৈরি হয় এবং উপযুক্ত ফোল্ডারে দেখা যায়। অগ্রাধিকার অনুযায়ী SLA ঘড়ি সঙ্গে সঙ্গে চালু হয়ে যায়।',
