            'card_category_title' => 'বিভাগ',
            'card_category_body' => 'সমস্যার ধরন নির্ধারণ করুন: হার্ডওয়্যার, সফটওয়্যার, নেটওয়ার্ক, অ্যাক্সেস, সাধারণ। রিপোর্টিংয়ে কাজে লাগে',
