            'card_enduser_title' => 'এন্ড ইউজার',
            'card_enduser_body' => 'যিনি অনুরোধটি তুলেছেন। বিদ্যমান ব্যবহারকারীর রেকর্ডের সঙ্গে যুক্ত করতে নাম বা ইমেল দিয়ে খুঁজুন',
