            'flow_in_progress' => 'চলমান',
            'flow_resolved' => 'সমাধান হয়েছে',
            'flow_closed' => 'বন্ধ',
            'triage_heading' => '<strong>টেনে এনে ছেড়ে বাছাই</strong>',
            'triage_body' => 'বাছাই করতে টিকিট খুলতে হয় না। টিকিটের তালিকা থেকে যেকোনো সারি একটি ফোল্ডারে টেনে ফেললেই এক ঝটকায় ফিল্ড হালনাগাদ হয়:',
            'triage_dept' => '<strong>বিভাগ ভিউ</strong> &mdash; পুনরায় নির্ধারণ করতে একটি বিভাগের ফোল্ডারে ফেলুন, দুটিই একসাথে হালনাগাদ করতে বিভাগের নিচের স্ট্যাটাস সাব-ফোল্ডারে ফেলুন, বিভাগ মুছে ফেলতে <strong>অনির্ধারিত</strong>-এ ফেলুন।',
            'triage_analyst' => '<strong>বিশ্লেষক ভিউ</strong> &mdash; ওই বিশ্লেষককে মালিক হিসেবে নিযুক্ত করতে তার ফোল্ডারে ফেলুন (এতে <code>assigned_analyst_id</code> ও <code>owner_id</code> দুটিই সেট হয়, ফলে রিডিং প্যানের মালিক ফিল্ড সঙ্গতিপূর্ণ থাকে), দুটিই একসাথে হালনাগাদ করতে স্ট্যাটাস সাব-ফোল্ডারে ফেলুন, নিযুক্ত ব্যক্তিকে সরাতে <strong>অনির্ধারিত</strong>-এ ফেলুন।',
            'triage_spring' => '<strong>স্প্রিং-লোডেড ফোল্ডার</strong> &mdash; টানার সময় একটি গুটানো ফোল্ডারের উপর ধরে রাখলে সেটি নিজে থেকে খুলে যায় (Outlook-এর মতো), ফলে আগে না ফেলেই ভেতরের যেকোনো স্ট্যাটাসে পৌঁছানো যায়।',
            'fullscreen_heading' => '<strong>ফুল-স্ক্রিন ভিউ</strong>',
            'fullscreen_body' => 'একটি টিকিটে মনোযোগ দিতে চাইলে &mdash; দীর্ঘ কথোপকথন, জটিল পরিবর্তন, বিস্তারিত উত্তর লেখা &mdash; ফুল-স্ক্রিন ভিউয়ে যান। ফোল্ডারের তালিকা ও টিকিটের তালিকা সরে যায়, কথোপকথন পুরো প্রস্থ জুড়ে আসে, আর প্রপার্টিগুলো (বিভাগ, ধরন, স্ট্যাটাস, উৎস, প্রথমবারে সমাধান, IT প্রশিক্ষণ, মালিক) ডানের একটি উল্লম্ব সাইডবারে চলে যায়।',
            'fullscreen_max' => '<strong>বড় করার আইকন</strong> &mdash; টিকিটের বিষয়ের লাইনের ডান প্রান্তে একটি ছোট আইকন। ফুল-স্ক্রিনে যেতে ক্লিক করুন; ৩-প্যানের বিন্যাসে ফিরতে আবার ক্লিক করুন।',
            'fullscreen_dbl' => '<strong>সারিতে ডাবল-ক্লিক</strong> &mdash; তালিকার যেকোনো টিকিটে ডাবল-ক্লিক করলে সেটি সরাসরি ফুল-স্ক্রিনে খোলে, Outlook-এর "এটি সত্যিই খুলুন" ভঙ্গির মতো।',
            'fullscreen_sticks' => '<strong>নির্বাচন বদলালেও থাকে</strong> &mdash; একবার ফুল-স্ক্রিনে গেলে পরের টিকিটে গেলেও আপনি সেখানেই থাকেন। কোনো টিকিট নির্বাচন না করে পেজ রিলোড (F5) করলে ডিফল্ট ৩-কলামের বিন্যাসে ফিরে যায়, ফলে ফোল্ডারের তালিকা লুকানো অবস্থায় আটকে যাওয়ার সম্ভাবনা নেই।',
            'rightclick_heading' => '<strong>দ্রুত অ্যাকশনের জন্য রাইট-ক্লিক</strong>',
            'rightclick_body' => 'একটি কনটেক্সট মেনু খুলতে তালিকার যেকোনো টিকিটে রাইট-ক্লিক করুন। মেনুর উপরে টিকিটের রেফারেন্স দেখায় যাতে আপনি জানেন কিসের উপর কাজ করছেন, আর প্রতিটি অ্যাকশন রিডিং প্যানে বর্তমানে যা খোলা আছে তা <em>না</em> বদলে রাইট-ক্লিক করা টিকিটে কাজ করে &mdash; টিকিট A পড়ার সময় নিজের জায়গা না হারিয়ে টিকিট B বাছাই করতে হলে কাজে লাগে।',
            'rightclick_status' => '<strong>স্ট্যাটাস ঠিক করুন &rarr;</strong> &mdash; প্রতিটি সক্রিয় স্ট্যাটাস তার রঙের নমুনা সহ দেখানো ফ্লাইআউট সাবমেনু। আপনার খোলা টিকিটেই রাইট-ক্লিক করলে বর্তমান মানের পাশে একটি টিক দেখা যায়। বেছে নিলেই টিকিট হালনাগাদ হয়, অডিট ট্রেইলে একটি এন্ট্রি লেখা হয়, ফোল্ডারের সংখ্যা রিফ্রেশ হয় এবং প্রযোজ্য হলে রিডিং প্যানের স্ট্যাটাস ড্রপডাউন মিলে যায়।',
            'rightclick_priority' => '<strong>অগ্রাধিকার ঠিক করুন &rarr;</strong> &mdash; একই ফ্লাইআউট ধরন, সক্রিয় অগ্রাধিকারের তালিকা থেকে নেওয়া এবং প্রতিটির রঙ নমুনা হিসেবে দেখানো। প্রথম সারিটি হলো নির্ধারণ মুছে ফেলার জন্য একটি <em>(কোনো অগ্রাধিকার নেই)</em> বিকল্প (অগ্রাধিকার ফাঁকা রাখা যায়)।',
            'rightclick_assign' => '<strong>নিযুক্ত করুন &rarr;</strong> &mdash; লোড হওয়া প্রতিটি বিশ্লেষককে ধূসর আদ্যক্ষরের চিপ সহ দেখানো সাবমেনু, আর মুছে ফেলার জন্য একদম উপরে একটি <em>(অনির্ধারিত)</em> সারি। বেছে নিলে <code>assigned_analyst_id</code> এবং <code>owner_id</code> দুটিই সেট হয়, ফলে রিডিং প্যানের মালিক ফিল্ড সঙ্গতিপূর্ণ থাকে।',
            'rightclick_cmdb' => '<strong>CMDB অবজেক্ট যুক্ত করুন&hellip;</strong> &mdash; টাইপ করতে করতে খোঁজার একটি পিকার খোলে। যুক্ত করতে কোনো ফলাফলে ক্লিক করুন, তারপর বেছেই চলুন &mdash; ইনপুট খালি হয়ে পরেরটির জন্য ফোকাস পায়, আর মোডালের ভেতরের একটি "সম্প্রতি যুক্ত" লগ সবুজ টিক নিশ্চিতকরণের চলমান তালিকা দেখায়।',
            'rightclick_time' => '<strong>সময় রেকর্ড করুন&hellip;</strong> &mdash; মিনিট, একটি তারিখ-সময় পিকার (ডিফল্ট "এখন", তাই পেছনের তারিখও দেওয়া যায়) এবং একটি ঐচ্ছিক নোট বক্স সহ একটি মোডাল খোলে।',
            'rightclick_phone' => '<strong>ফোনে</strong> একই মেনুটি ফুল-স্ক্রিন প্যানেল হিসেবে খুলতে একটি টিকিট আধা সেকেন্ড চেপে ধরুন। যে বিকল্পে আরও বিকল্প আছে &mdash; স্ট্যাটাস ঠিক করুন, অগ্রাধিকার ঠিক করুন, নিযুক্ত করুন &mdash; সেটি সেগুলোর দিকে সরে যায়, ফেরার জন্য আছে <strong>পিছনে</strong>।',
            'rightclick_tip' => 'কনটেক্সট মেনু দিয়ে আপনি যে টিকিটে কাজ করছেন সেটি যদি রিডিং প্যানে খোলা টিকিটটিই হয়, তাহলে মোডাল বন্ধ হলে সেখানকার প্রাসঙ্গিক অংশ (স্ট্যাটাস / অগ্রাধিকার ড্রপডাউন, CMDB অবজেক্ট, সময়ের এন্ট্রি) নিজে থেকে রিফ্রেশ হয়, ফলে UI মিলে থাকে।',
            'time_heading' => '<strong>সময় রেকর্ড করা</strong>',
            'time_body' => 'টিকিটে কাটানো সময় রিডিং প্যানের একটি নির্দিষ্ট <strong>সময়ের এন্ট্রি</strong> অংশে লগ হয়, যা যুক্ত CMDB অবজেক্টের প্যানেল ও নোট প্যানেলের মাঝখানে থাকে। হেডারে চলমান মোট দেখায় (যেমন "মোট 2h 30m"), আর নিচের প্রতিটি এন্ট্রিতে কাটানো সময়, বিশ্লেষক, তারিখ এবং আপনার যোগ করা যেকোনো নোট দেখায়।',
            'time_step1' => '<strong>ইনলাইন ফর্ম</strong> &mdash; সংখ্যার ইনপুটে কাটানো মিনিট লিখুন, নোট ইনপুটে একটি ঐচ্ছিক সংক্ষিপ্ত বিবরণ দিন, আর <strong>যোগ করুন</strong>-এ ক্লিক করুন। নতুন এন্ট্রি আপনার নাম ও বর্তমান টাইমস্ট্যাম্প সহ তালিকার একদম উপরে সঙ্গে সঙ্গে দেখা যায়।',
            'time_step2' => '<strong>রাইট-ক্লিকে পেছনের তারিখ</strong> &mdash; আগে রেকর্ড করতে ভুলে যাওয়া সময় লগ করতে হলে তালিকায় টিকিটে রাইট-ক্লিক করে <strong>সময় রেকর্ড করুন&hellip;</strong> বেছে নিন। মোডালে একটি তারিখ-সময় পিকার আছে, যাতে কাজটি আসলে যখন হয়েছিল সেই সময় এন্ট্রিতে বসাতে পারেন।',
            'time_step3' => '<strong>নিজের এন্ট্রি মুছুন</strong> &mdash; আপনার লগ করা এন্ট্রির পাশে একটি ছোট &times; বোতাম দেখা যায়। ক্লিক করুন (এবং নিশ্চিত করুন) সফট-ডিলিট করতে &mdash; অডিটের জন্য সারিটি <code>is_active = 0</code> নিয়ে ডেটাবেসে থাকে, কিন্তু তালিকা থেকে মিলিয়ে যায়। অন্য বিশ্লেষকদের এন্ট্রি মোছা যায় না।',
            'time_tip1' => 'সময় সাধারণ মিনিট হিসেবে (45 min, 90 min ইত্যাদি) সংরক্ষিত হয় এবং UI-তে <code>45m</code> বা <code>1h 30m</code> হিসেবে দেখায় &mdash; ছোট সমাধানের জন্য যথেষ্ট সূক্ষ্ম, দশমিক-ঘণ্টা রাউন্ডিংয়ের ঝামেলা নেই।',
            'time_tip2' => 'প্রতিটি ফিল্ড পরিবর্তন টিকিটের কার্যকলাপের ট্রেইলে রেকর্ড হয়। কে কখন কী বদলেছে তা আপনি সবসময় দেখতে পারেন, যা অডিট সম্মতি এবং বিশ্লেষকদের মধ্যে হস্তান্তরের জন্য অপরিহার্য।',
        ],
        'comments' => [
            'heading' => 'মন্তব্য &amp; সংযুক্তি',
            'intro' => 'অ্যাক্টিভিটি ট্রেইল প্রতিটি টিকিটের প্রাণকেন্দ্র। এটি নেওয়া প্রতিটি পদক্ষেপ &mdash; মন্তব্য, ফিল্ড পরিবর্তন, পাঠানো ইমেল এবং সংযুক্ত ফাইল &mdash; কালানুক্রমিক টাইমলাইনে ধরে রাখে, যা একটি সাপোর্ট অনুরোধের পুরো গল্প বলে।',
            'adding_heading' => '<strong>মন্তব্য যোগ করা</strong>',
            'step1' => '<strong>টিকিটটি খুলুন</strong> &mdash; ইনবক্সে যেকোনো টিকিটে ক্লিক করে তার রিডিং পেন লোড করুন। পুরো অ্যাক্টিভিটি ট্রেইল এবং নিচের মন্তব্য বক্স দেখতে স্ক্রল করে নিচে যান।',
            'step2' => '<strong>আপনার নোট লিখুন</strong> &mdash; মন্তব্য এডিটর খুলতে Add Note বোতাম ব্যবহার করুন। নোট ডিফল্টভাবে অভ্যন্তরীণ, শুধু সার্ভিস ডেস্কের বিশ্লেষকরা দেখতে পান।',
            'step3' => '<strong>ইমেলে উত্তর দিন বা ফরওয়ার্ড করুন</strong> &mdash; শেষ ব্যবহারকারী বা তৃতীয় পক্ষকে বার্তা পাঠাতে Reply বা Forward অ্যাকশন ব্যবহার করুন। ইমেলটি পাঠানো বার্তার বিষয়বস্তুসহ অ্যাক্টিভিটি ট্রেইলে লগ হয়।',
            'files_heading' => '<strong>ফাইল সংযুক্তি</strong>',
            'files_body' => 'স্ক্রিনশট, লগ, নথি বা যেকোনো সহায়ক ফাইল সরাসরি টিকিটে সংযুক্ত করুন। ফাইল সংযুক্তি ড্রপ জোনে টেনে আনা যায় অথবা ফাইল ব্রাউজার দিয়ে বেছে নেওয়া যায়। সংযুক্তি সার্ভারে সংরক্ষিত থাকে এবং টিকিটের অ্যাক্টিভিটি ট্রেইলের সাথে যুক্ত হয়, তাই কিছুই হারায় না।',
            'audit_heading' => '<strong>অডিট লগিং</strong>',
            'audit_body' => 'বিশ্লেষককে কিছু করতে না হয়েই অ্যাক্টিভিটি ট্রেইল স্বয়ংক্রিয়ভাবে প্রতিটি পদক্ষেপ রেকর্ড করে। অগ্রাধিকার Medium থেকে High করা হলে পুরোনো ও নতুন মান ধরা থাকে। টিকিট পুনরায় বরাদ্দ করা হলে আগের ও নতুন বিশ্লেষক দুজনেরই নাম লগ হয়। এতে একটি সম্পূর্ণ, ছেড়াফাঁড়ার অযোগ্য ইতিহাস তৈরি হয়, যা ITIL অডিটের প্রয়োজন মেটায় এবং টিকিট কীভাবে সামলানো হচ্ছে তা ম্যানেজারদের বুঝতে সাহায্য করে।',
            'tip' => 'ইমেলে উত্তর দেওয়ার সময় একই অ্যাকশনে Cc প্রাপক যোগ করতে এবং ফাইল সংযুক্ত করতে পারেন। পুরো ইমেল কথোপকথন টিকিটের অ্যাক্টিভিটি ট্রেইলে থ্রেড হয়ে থাকে, ফলে সব যোগাযোগ এক জায়গায় থাকে।',
        ],
        'ai' => [
            'heading' => 'AI টুল',
            'intro' => 'টিকিটের কাজের ধারায় Claude-চালিত দুটি ফিচার আছে: <strong>Reply Cleanup</strong> একটি এলোমেলো খসড়াকে সঠিকভাবে সাজানো ইমেলে রূপ দেয়, আর <strong>Ask AI</strong> টিকিটের প্রসঙ্গ ব্যবহার করে স্বাভাবিক ভাষায় নলেজ বেস অনুসন্ধান করে।',
            'cleanup_heading' => '<strong>Reply Cleanup &mdash; রিপ্লাই এডিটরের ✨ বোতাম</strong>',
            'cleanup_body' => 'উত্তরে একটি দ্রুত এলোমেলো খসড়া (বা শুধু বুলেট পয়েন্ট, যেমন *"need to restart the print service, take screenshot for them"*) লিখে <strong>✨ Cleanup</strong> বোতামে ক্লিক করুন। Claude এটিকে সঠিকভাবে সাজানো ইমেল হিসেবে নতুন করে লেখে &mdash; অনুরোধকারীর নামে একটি <em>Dear [name],</em> সম্বোধন যোগ করে, ব্যাকরণ ঠিক করে, কনফিগার করা টোন প্রয়োগ করে এবং <em>Kind regards,</em> দিয়ে শেষ করে। প্রম্পটটি এমনভাবে আটকানো যে এটি কারিগরি তথ্য বানাবে না, মনগড়া দুঃখপ্রকাশ করবে না, বা আপনার লেখার বাইরে বিষয়বস্তু বাড়াবে না।',
            'cleanup_streams' => '<strong>লাইভ স্ট্রিম হয়</strong> &mdash; Claude যেমন লিখতে থাকে, নতুন লেখা তেমনই এডিটরে দেখা যায় (স্পিনারের সামনে অপেক্ষা করতে হয় না)।',
            'cleanup_undo' => '<strong>৩০ সেকেন্ডের জন্য Undo লিঙ্ক</strong> &mdash; Claude যদি লেখাটি নষ্ট করে ফেলে, তাই নতুন করে লেখা শেষ হওয়ার ৩০ সেকেন্ড পর্যন্ত এডিটরের নিচে একটি ছোট <em>Undo</em> লিঙ্ক দেখা যায়, যা মূল খসড়া ফিরিয়ে আনে।',
            'cleanup_tone' => '<strong>টোন অনুযায়ী</strong> &mdash; <strong>Settings &rarr; Reply Cleanup</strong>-এ তিনটি টোন প্রিসেট কনফিগার করা যায়: <em>Friendly</em> (ডিফল্ট), <em>Formal</em>, <em>Brief</em>। আপনার দলের নিজস্ব ধরনের সাথে যেটি মেলে সেটি বেছে নিন।',
            'cleanup_key' => '<strong>নিজস্ব API key</strong> &mdash; RFP / নলেজ / ওয়ার্কফ্লো AI ফিচার থেকে আলাদা Anthropic key, যাতে এর ব্যবহার Anthropic বিলিং ড্যাশবোর্ডে আলাদা লাইন হিসেবে দেখা যায়। <strong>Settings &rarr; Reply Cleanup</strong>-এ কনফিগার করা হয়।',
            'cleanup_tip' => 'Cleanup সবচেয়ে ভালো কাজ করে "আমি এটা চেষ্টা করেছি, দয়া করে X চেষ্টা করুন" ধাঁচের নিয়মিত উত্তরে। দীর্ঘ, সূক্ষ্ম বার্তা নিজে লেখাই ভালো &mdash; AI কাঠামো সাজাতে দক্ষ, কিন্তু আপনার নির্দিষ্ট পরিবেশ জানে না।',
            'ask_heading' => '<strong>Ask AI &mdash; টিকিট টুলবারের 🤖 বোতাম</strong>',
            'ask_body' => 'টিকিট টুলবারে <strong>Ask AI</strong> বোতামে (🤖) ক্লিক করে একটি স্লাইড-ইন চ্যাট প্যানেল খুলুন, যা খোলা টিকিটের বিষয়, বিষয়বস্তু এবং রিডিং পেনের প্রসঙ্গ জানে। এটিকে প্রশ্ন করুন, যেমন *"have we seen this before?"* বা *"what\'s the usual fix for this error?"* — এটি <a href="../knowledge/" style="color:#0078d4;">নলেজ</a> বেসে (Claude + OpenAI এমবেডিং দিয়ে) অর্থভিত্তিকভাবে অনুসন্ধান করে প্রাসঙ্গিক নিবন্ধ দেখায়, খোলার জন্য সরাসরি লিঙ্কসহ।',
            'ask_context' => '<strong>প্রসঙ্গ-সচেতন</strong> &mdash; প্যানেলটি জানে আপনি কোন টিকিট দেখছেন, তাই সাধারণ প্রশ্ন করলেও এটি প্রাসঙ্গিক তথ্য নিজেই বুঝে নেয়।',
            'ask_linked' => '<strong>লিঙ্ক করা নিবন্ধ</strong> &mdash; পরামর্শগুলো ক্লিকযোগ্য এবং মিলে যাওয়া নলেজ নিবন্ধ নতুন ট্যাবে খোলে।',
            'ask_shared' => '<strong>নলেজ মডিউলের সাথে ভাগ করা</strong> &mdash; AI নলেজ AI অনুসন্ধানের মতোই একই key + মডেল ব্যবহার করে, তাই একবার কনফিগার করলে দুটিই পাবেন। সেটআপের বিস্তারিত জানতে নলেজ মডিউলের সহায়তা দেখুন।',
        ],
        'csat' => [
            'heading' => 'গ্রাহক সন্তুষ্টি জরিপ (CSAT)',
            'intro' => 'টিকিট সমাধান হলে অনুরোধকারীকে ইমেলে ১&ndash;৫ স্কেলের সন্তুষ্টি জরিপ পাঠান, লগইন ছাড়া একটি ল্যান্ডিং পেজে উত্তর সংগ্রহ করুন এবং আলাদা অ্যানালিটিক্স পেজে বিশ্লেষক অনুযায়ী প্রবণতা ট্র্যাক করুন।',
            'modes_heading' => '<strong>দুটি ট্রিগার মোড &mdash; একটি বেছে নিন</strong>',
            'mode_auto' => '<strong>বন্ধ হলে স্বয়ংক্রিয়</strong> &mdash; টিকিট যেকোনো বন্ধ স্ট্যাটাসে গেলে জরিপ স্বয়ংক্রিয়ভাবে সারিতে যায়। বিশ্লেষককে কিছুই করতে হয় না &mdash; সমাধানই জরিপ চালু করে।',
            'mode_manual' => '<strong>শুধু ম্যানুয়াল</strong> &mdash; বিশ্লেষক জিজ্ঞাসা করতে চাইলে টিকিট টুলবারের ⭐ <strong>Feedback</strong> বোতামে ক্লিক করেন। টিকিটভেদে সিদ্ধান্ত নিতে চাইলে কাজে লাগে যে মতামত চাওয়া হবে কি না।',
            'mode_off' => '<strong>বন্ধ</strong> &mdash; ফিচার নিষ্ক্রিয়; কোনো জরিপ ইমেল পাঠানো হয় না।',
            'modes_choose' => '<strong>Tickets &rarr; Settings &rarr; CSAT</strong>-এ বেছে নিন। <em>auto</em> মোডেও ম্যানুয়াল বোতাম কাজ করে &mdash; প্রয়োজনে যে টিকিটে আগেই জরিপ পাঠানো হয়েছে, সেখানে বিশ্লেষক আবার মতামত চাইতে পারেন।',
            'template_heading' => '<strong>ইমেল টেমপ্লেট</strong>',
            'template_body' => 'জরিপ ইমেলের বিষয়বস্তু আসে বিদ্যমান <strong>Email templates</strong> ট্যাব থেকে &mdash; <strong>CSAT survey</strong> ইভেন্টসহ একটি টেমপ্লেট তৈরি করুন (<em>Ticket assigned</em> / <em>Ticket closed</em>-এর পাশে নতুন ইভেন্ট) এবং রেটিং URL যেখানে দেখাতে চান সেখানে <code>[csat_link]</code> মার্জ কোড বসান। স্ট্যান্ডার্ড মার্জ কোড (<code>[requester_name]</code>, <code>[ticket_reference]</code>, <code>[analyst_name]</code>) যথারীতি পাওয়া যায়।',
            'template_tip' => 'কোনো সক্রিয় CSAT টেমপ্লেট না থাকলে <em>Feedback</em> বোতাম স্পষ্ট ত্রুটি দেখিয়ে অস্বীকার করে এবং স্বয়ংক্রিয় ট্রিগার নীরবে বাদ দেয় &mdash; তাই অকেজো জরিপ লিঙ্ক কখনোই তৈরি হয় না।',
            'survey_heading' => '<strong>জরিপ পেজ</strong>',
            'survey_body' => 'অনুরোধকারী ইমেলের লিঙ্কে ক্লিক করলে লগইন ছাড়া একটি পেজে পৌঁছান, যেখানে ১&ndash;৫ বাছাই এবং ঐচ্ছিক মন্তব্য বক্স থাকে। <strong>Settings &rarr; CSAT</strong>-এ দুটি ভিজ্যুয়াল স্টাইল কনফিগার করা যায়:',
            'survey_stars' => '<strong>Stars</strong> &mdash; ক্লাসিক হোভারে ভরাট হওয়ার আচরণ। ৩ নম্বর তারায় হোভার করলে ১+২+৩ সোনালি রঙে ভরে যায়। লক করতে ক্লিক করুন।',
            'survey_emojis' => '<strong>Emojis</strong> &mdash; ৫টি মুখ 😡 🙁 😐 🙂 😀 ৪০% অস্বচ্ছতায় ধূসর অবস্থায় শুরু হয়; হোভার করা বা বাছাই করাটি ১.২৫&times; স্কেলে পূর্ণ রঙে ফিরে আসে। লক করতে ক্লিক করুন।',
            'survey_store' => 'দুটি মোডই একই ১&ndash;৫ সংখ্যা সংরক্ষণ করে, তাই কোন স্টাইল ব্যবহার হলো তা নির্বিশেষে ড্যাশবোর্ড ও গড় একইভাবে কাজ করে। জরিপের URL একবারের জন্য &mdash; ব্যবহারকারী জমা দিলে একই লিঙ্কে আর জমা নেওয়া হয় না।',
            'chat_heading' => '<strong>চ্যাট গ্রাহকদের তাদের চ্যাটেই জিজ্ঞাসা করা</strong>',
            'chat_body' => '<strong>Ask chat customers in their chat</strong> টিক দেওয়া থাকলে, যে গ্রাহক WhatsApp, Telegram, Slack, Microsoft Teams বা Mattermost-এ লিখেছেন তাঁকে ইমেলের বদলে সেই চ্যাটেই জিজ্ঞাসা করা হয় &mdash; Telegram, Teams ও Mattermost-এ পাঁচটি বোতাম, অন্যত্র &ldquo;একটিমাত্র অঙ্কে উত্তর দিন&rdquo;। তাঁদের উত্তর ইমেল জরিপের মতোই একই ফলাফলে যায়।',
            'chat_rules' => 'WhatsApp-এ কেবল তখনই জিজ্ঞাসা করা হয় যখন এর ২৪ ঘণ্টার উত্তর-উইন্ডো খোলা থাকে; তার বাইরে, বা চ্যাট বার্তা পাঠানো না গেলে, ইমেল জরিপ ব্যবহার করা হয়। একটি অঙ্ক রেটিং হিসেবে গণ্য হয় কেবল প্রশ্নের ঠিক পরেই &mdash; একই চ্যাটে, এক সপ্তাহের মধ্যে এবং গ্রাহক আর কিছু লেখার আগে &mdash; তাই বিশ্লেষকের প্রশ্নের উত্তরে &ldquo;3&rdquo; লেখা একটি সাধারণ বার্তাই থাকে। আপগ্রেডের পর বন্ধ; নতুন ইনস্টলে চালু।',
            'analytics_heading' => '<strong>অ্যানালিটিক্স পেজ</strong>',
            'analytics_body' => 'নেভ বারে (Rota ও Settings-এর মাঝে) ⭐ <strong>CSAT</strong> বোতামে ক্লিক করে <code>tickets/csat/</code>-এ অ্যানালিটিক্স ড্যাশবোর্ড খুলুন। সময়সীমা বাছাই করা যায়: ৭ / ৩০ / ৯০ / ৩৬৫ দিন।',
            'card_kpi_title' => 'KPI টাইল',
            'card_kpi_body' => 'গড় রেটিং (৫-এর মধ্যে), উত্তরের সংখ্যা, উত্তরের হার (উত্তর ÷ পাঠানো)',
            'card_dist_title' => 'স্কোর বণ্টন',
            'card_dist_body' => '১–৫ রেটিংয়ের বার চার্ট, সঠিক সংখ্যা ও শতাংশসহ',
            'card_leader_title' => 'বিশ্লেষক অনুযায়ী লিডারবোর্ড',
            'card_leader_body' => 'প্রতি বিশ্লেষকের গড় রেটিং + উত্তরের সংখ্যা, গড় অনুযায়ী উচ্চ থেকে নিম্ন ক্রমে সাজানো। উন্নয়নমূলক আলোচনার জন্য ব্যবহার করুন',
            'card_recent_title' => 'সাম্প্রতিক উত্তর',
            'card_recent_body' => 'রেটিংগুলো সবচেয়ে নতুন আগে, প্রতি পেজে ২৫টি, মুক্ত-লেখা মন্তব্য ও যিনি দিয়েছেন সেই গ্রাহকসহ, মূল টিকিটে ফিরে যাওয়ার লিঙ্কসহ',
            'analytics_filters' => 'শিরোনামের নিচের ফিল্টার দিয়ে পেজ সীমিত করুন: একটি <strong>From / To</strong> তারিখ সীমা (দিনের বোতামের বদলে), একটি <strong>Rating</strong> ব্যান্ড (Positive 4-5, Neutral 3, Negative 1-2), একটি <strong>Analyst</strong> এবং একটি <strong>Customer</strong>। বিশ্লেষক ও গ্রাহক পেজের প্রতিটি সংখ্যাকে সীমিত করে; রেটিং ব্যান্ড কেবল উত্তরের তালিকাকে সীমিত করে, যাতে গড়ের অর্থ বজায় থাকে। ফোনে ফিল্টারগুলো স্ক্রিনের নিচে <strong>Filters</strong> বোতামের পিছনে থাকে। ফিল্টার করা পেজ বুকমার্ক করা যায়।',
            'analytics_company' => 'প্রতিটি সংখ্যা হেডারের <strong>company switcher</strong>-কে অনুসরণ করে: আপনার বাছাই করা কোম্পানি, অথবা <strong>All companies</strong>-এর অধীনে আপনি যেসব কোম্পানি দেখতে পান সেগুলো সব।',
            'analytics_tip' => 'টিকিট পুনরায় বরাদ্দ হলেও বিশ্লেষক অনুযায়ী হিসাব টিকে থাকে, কারণ বিশ্লেষকের আইডি পাঠানোর সময়ই জরিপের সারিতে ধরা হয়, লাইভ খুঁজে দেখা হয় না। বন্ধ হওয়ার আগে টিকিট হাতবদল হলে, যে বিশ্লেষক সেটি আসলে বন্ধ করেছেন রেটিং তাঁর।',
            'one_heading' => '<strong>প্রতি টিকিটে একটি জরিপ</strong>',
            'one_body' => '<em>One survey per ticket</em> চালু থাকলে (ডিফল্ট), পুনরায় খোলা-তারপর-বন্ধ হওয়া টিকিটে আরেকটি জরিপ যায় কেবল বিশ্লেষক ম্যানুয়ালি ট্রিগার করলে &mdash; এতে বারবার ঘুরতে থাকা অস্থির টিকিটে জরিপের স্প্যাম বন্ধ হয়। প্রতিটি বন্ধের সময় নতুন জরিপ পাঠাতে চাইলে এটি বন্ধ করুন।',
        ],
        'users' => [
            'heading' => 'ব্যবহারকারী ব্যবস্থাপনা',
            'intro' => '<strong>ব্যবহারকারী</strong> নেভ বোতামটি <code>tickets/users.php</code> খোলে &mdash; প্রতিটি এন্ড ইউজারের (যাঁরা টিকিট তোলেন, বিশ্লেষকরা নন) একটি ডিরেক্টরি, প্রত্যেকের টিকিটের ইতিহাসসহ।',
            'p_intro' => 'ব্যবহারকারীরা চারটি প্রতিক্রিয়াশীল উপায়ে সিস্টেমে আসেন &mdash; পোর্টালে নিজে নিবন্ধন, নতুন প্রেরকের ইনবাউন্ড ইমেল, মেইলবক্স পোলার, অথবা ওয়ার্কফ্লো ইঞ্জিন কোনো ট্রিগার হওয়া টিকিট থেকে একজনকে তৈরি করলে। এতে বেশির ভাগ ক্ষেত্র সামলানো যায়, কিন্তু ব্যবহারকারী পৃষ্ঠায় আপনি আগে থেকে ব্যবহারকারী <strong>তৈরি</strong>ও করতে পারেন (যেমন নতুন যোগ দেওয়া কেউ, যাঁর শিগগিরই অ্যাক্সেস লাগবে) এবং বিদ্যমান সারিগুলো <strong>সম্পাদনা</strong> বা <strong>মুছে</strong> ফেলতে পারেন।',
            'add_heading' => '<strong>ব্যবহারকারী যোগ করুন</strong>',
            'add_body' => 'ব্যবহারকারী-তালিকার হেডারের <strong>যোগ</strong> বোতামটি ব্যক্তি এডিটর খোলে। <strong>অ্যাসেট &rarr; ব্যবহারকারী</strong> একই এডিটর খোলে, তাই আপনি যে স্ক্রিনেই থাকুন, একজন ব্যক্তিকে একইভাবে যোগ ও পরিবর্তন করা যায়:',
            'add_email' => '<strong>ইমেল</strong> &mdash; ঐচ্ছিক, কারণ যাঁরা ডিরেক্টরির মাধ্যমে সাইন ইন করেন তাঁদের মেইলবক্স নাও থাকতে পারে; তাঁদের বদলে সাইন-ইন নাম দিয়ে খুঁজে পাওয়া যায়। ইমেল ঠিকানা বা প্রদর্শন নাম, যেকোনো একটি দিন। ঠিকানাটি অনন্য হতে হবে এবং কোনো বিশ্লেষকের হতে পারবে না।',
            'add_names' => '<strong>প্রদর্শন নাম / পছন্দের নাম</strong> &mdash; ঐচ্ছিক। পছন্দের নাম হলো ইমেলে ব্যবহারকারী নিজেকে যে নামে সম্বোধিত দেখেন (যেমন <em>"Ed Mozley"</em>-এর বদলে <em>"Ed"</em>)।',
            'add_password' => '<strong>পাসওয়ার্ড</strong> &mdash; ঐচ্ছিক। ফাঁকা রাখলে একটি <em>পাসওয়ার্ডবিহীন</em> অ্যাকাউন্ট তৈরি হয় &mdash; ইনবাউন্ড-টিকিটের ব্যবহারকারীরা ঠিক এই অবস্থাতেই শুরু করেন। ব্যবহারকারী পরে সেলফ-সার্ভিস পোর্টালের নিবন্ধন ধাপে নিজের পাসওয়ার্ড দিয়ে অ্যাকাউন্টটির দাবি নিতে পারেন।',
            'add_details' => '<strong>পদবি, বিভাগ, অফিস, ফোন, মোবাইল, কর্মচারী আইডি ও ম্যানেজার</strong> &mdash; সবই ঐচ্ছিক, এবং সবই লগইন নয়, <em>ব্যক্তিকে</em> বর্ণনা করে। পূরণ করা ভালো: <strong>অফিস</strong> বলে দেয় কেউ কোন সাইটে আছেন, যাতে খুঁজতে বেরোতে না হয়; <strong>ম্যানেজার</strong> রিপোর্টিং লাইন রেকর্ড করে (খুঁজতে নামের একটি অংশ লিখুন); আর যে পেরোল সিস্টেম ইমেল ঠিকানার কথা কখনো শোনেনি তার সাথে মেলানোর সময় <strong>কর্মচারী আইডি</strong> হলো জোড়ার চাবি। ডিরেক্টরি থেকে ইমপোর্ট করলে এগুলো সব পূরণ হয়েই আসে। CardDAV অ্যাড্রেস বুক কর্মচারী আইডি ও ম্যানেজার ছাড়া সবই পূরণ করে, কারণ কন্টাক্ট কার্ডে এ দুটি রাখার জায়গা নেই।',
            'managed_heading' => '<strong>অন্য কোথাও রক্ষণাবেক্ষণ করা ব্যক্তিরা</strong>',
            'source_body' => '<strong>একজন ব্যক্তি কোথা থেকে এসেছেন</strong> তাঁর বিবরণে লেখা থাকে (<em>Details from: Contoso AD - directory</em>), আর সার্চ বক্সের নিচের <strong>উৎস</strong> ফিল্টার শুধু একটি ডিরেক্টরি বা অ্যাড্রেস বুকের ব্যক্তিদের, অথবা শুধু FreeITSM-এ যোগ করাদের তালিকা দেখায়, প্রতিটির পাশে সংখ্যাসহ। কেউ কোনো উৎসের সাথে যুক্ত হলে এটি দেখা যায়।',
            'add_book_body' => '<strong>অ্যাড্রেস বুকে যোগ করুন।</strong> যিনি ইমেল করেছেন তিনি এখানে আছেন, কিন্তু কোনো অ্যাড্রেস বুকে নেই। কোনো অ্যাডমিনিস্ট্রেটর <em>অ্যানালিস্টদের এই অ্যাড্রেস বুকে ব্যক্তি যোগ করতে দিন</em> চালু করলে (সিস্টেম &rarr; অথেনটিকেশন, অ্যাড্রেস বুকের উপর), সেই ব্যক্তির সম্পাদনার পাশে একটি <strong>অ্যাড্রেস বুকে যোগ করুন</strong> বোতাম আসে। এটি আগে জিজ্ঞাসা করে, কার্ডে কী যাবে তা দেখায়, তারপর তাঁর কন্টাক্ট তৈরি করে সংযুক্ত করে &mdash; একই ব্যক্তি, কোনো কপি নয়। বইটিতে যাঁর ইমেল ঠিকানা আগে থেকেই আছে তাঁকে এটি যোগ করবে না (বদলে ইমপোর্ট চালান), এবং পরের ইমপোর্ট যেন নতুন কন্টাক্টটি তুলে নেয় তা নিশ্চিত করে, নয়তো কার্ডটি আবার সরিয়ে নেয়।',
            'managed_body' => 'যেখানে কোনো ব্যক্তিকে LDAP বা Active Directory থেকে, কিংবা CardDAV অ্যাড্রেস বুক থেকে ইমপোর্ট করা হয়েছে, সেখানে ওই উৎসের মালিকানাধীন বিবরণগুলো <strong>শুধু-পঠনযোগ্য</strong> এবং মোডাল সেগুলো ধূসর করে দেয়। যেখান থেকে এসেছে সেটিই সত্যের উৎস, আর পরের ইমপোর্ট এখানে লেখা সবকিছু ওভাররাইট করে দিত, তাই সংরক্ষণ গ্রহণ করে এক ঘণ্টা পরে চুপচাপ ফিরিয়ে না দিয়ে সরাসরি প্রত্যাখ্যান করা হয়। <strong>কোন</strong> বিবরণ তা নির্ভর করে উৎসের উপর: ডিরেক্টরি সাতটিরই মালিক, আর অ্যাড্রেস বুক পাঁচটির &mdash; কর্মচারী নম্বর বা রিপোর্টিং লাইন রাখার জায়গা তার নেই, তাই ওই দুটি আপনিই পূরণ করবেন। আর অ্যাড্রেস বুকে <em>পরিবর্তন ফেরত লেখা</em> চালু থাকলে কোনোটিই লক থাকে না: আপনি যা লেখেন তা কন্টাক্ট কার্ডে পাঠানো হয়, তাই পরের ইমপোর্টের ফেরানোর মতো কিছু থাকে না। রেকর্ডের বাকি সবকিছু, তাঁর কোম্পানি ও পাসওয়ার্ডসহ, সবসময় সম্পাদনাযোগ্য।',
            'edit_heading' => '<strong>ব্যবহারকারী সম্পাদনা করুন</strong>',
            'edit_body' => 'তালিকা থেকে একজন ব্যবহারকারী নির্বাচন করুন, তারপর বিস্তারিত হেডারে <strong>সম্পাদনা</strong> ক্লিক করুন। একই এডিটর, আগে থেকে পূরণ করা। পাসওয়ার্ড ছাড়া সংরক্ষণ করলে বিদ্যমান হ্যাশ অক্ষত থাকে; একটি দিলে তা রিসেট হয়ে যায়। তাঁর ম্যানেজার যদি এমন কোনো কোম্পানির কেউ হন যা আপনি দেখতে পান না, ম্যানেজার বক্সে তা বলা থাকে এবং আপনি অন্য কাউকে না বাছলে ম্যানেজার যেমন আছেন তেমনই থাকেন।',
            'signin_body' => '<strong>সাইন ইন করেন</strong> দেখায় একজন ব্যক্তি কোন সিঙ্গল সাইন-অন প্রদানকারীর সাথে যুক্ত। এর পাশের <strong>লিঙ্ক খুলুন</strong>, নিশ্চিত করার পর, সেই সংযোগ সরিয়ে দেয় যাতে তাঁর পরের সাইন-ইন নতুনভাবে শুরু হয় &mdash; যিনি অন্য প্রদানকারীতে গেছেন, বা ভুল অ্যাকাউন্টের সাথে যুক্ত হয়েছিলেন তাঁর জন্য। ডিরেক্টরি সিঙ্ক দিয়ে পরিচালিত ব্যক্তিদের জন্য এটি দেওয়া হয় না, কারণ সিঙ্ক তাঁদের আবার যুক্ত করে দিত।',
            'company_body' => 'একাধিক থাকলে <strong>কোম্পানি</strong> দেখা যায়। নতুন ব্যক্তির ক্ষেত্রে ফাঁকা রাখলে ইমেল ঠিকানা থেকে কোম্পানি বের করা হয়; বিদ্যমান ব্যক্তির ক্ষেত্রে ফাঁকা মানে কোনো কোম্পানি নেই, আর তাঁর টিকিট ট্রায়াজে যায়।',
            'managers_heading' => '<strong>ম্যানেজার</strong>',
            'managers_body' => 'সেলফ-সার্ভিস পোর্টালে একজন ব্যক্তিকে <strong>ম্যানেজার</strong> করা যায়: তিনি একটি <strong>টিম টিকিট</strong> ট্যাব পান, যেখানে তাঁর ম্যানেজ করা ব্যক্তিদের টিকিট তালিকাভুক্ত থাকে। কোনো অ্যাডমিনিস্ট্রেটর <strong>সিস্টেম &rarr; ম্যানেজার</strong>-এর অধীনে চালু না করা পর্যন্ত এটি বন্ধ থাকে; সেখানেই ঠিক হয় ম্যানেজাররা ওই টিকিটের উত্তর দিতে বা বন্ধ করতে পারবেন কি না, এবং গোপনীয় টিকিটের কতটা দেখবেন (ডিফল্টে কিছুই নয়)।',
            'managers_sources' => 'কেউ ম্যানেজার হন দুইভাবে, একসাথে দুটিই: অন্যদের রেকর্ডে তিনি <strong>ম্যানেজার</strong> (হাতে বা আপনার ডিরেক্টরি থেকে), এবং তাঁর জন্য <strong>ম্যানেজমেন্ট লাইন</strong> সেট করা আছে। সম্পাদনার পাশে <strong>ম্যানেজার অ্যাক্সেস</strong> ক্লিক করে সেই ব্যক্তির জন্য একটি পূর্ণ-স্ক্রিন পৃষ্ঠা খুলুন, যেখানে আপনি তাঁকে সবাইকে, নির্দিষ্ট ব্যক্তিদের, ব্যক্তি-গ্রুপ, বিভাগ বা তাঁর পুরো রিপোর্টিং লাইন দিতে পারেন, এবং ব্যক্তিদের <strong>বাদ</strong> দিতে পারেন &mdash; বাদ দেওয়াই সবসময় জেতে, ম্যানেজার ফিল্ডের উপরেও। পৃষ্ঠাটি দেখায় তিনি কতজনকে দেখতে পাবেন এবং তাঁদের তালিকা করে, যেন ম্যানেজাররা আগে থেকেই চালু আছে ধরে হিসাব করা, যাতে চালু করার আগেই যাচাই করতে পারেন। তালিকার যেকোনো ব্যক্তিকে ক্লিক করলে দেখা যায় ম্যানেজার <strong>কেন</strong> তাঁকে দেখতে পান, এবং কীভাবে তা থামানো যায়।',
            'managers_rules' => 'একজন ম্যানেজার শুধু নিজের কোম্পানির ব্যক্তিদের দেখেন, কখনো নিজেকে নন, এবং চাকরি ছেড়ে দিলে আর কিছুই নয়। বিভাগ মেলানো হয় প্রতিটি ব্যক্তির উপর লেখা নাম দিয়ে, তাই নাম বদলালে বিভাগটি আর মেলে না &mdash; যে বিভাগ-লাইন কাউকে মেলায় না, পৃষ্ঠা এবং সিস্টেম &rarr; ম্যানেজার সে বিষয়ে সতর্ক করে। ডিফল্টে শুধু অ্যাডমিনিস্ট্রেটররা ম্যানেজমেন্ট লাইন বদলাতে পারেন; সিস্টেম &rarr; ম্যানেজার সেটি ব্যক্তি সম্পাদনা করতে পারেন এমন যে কারও জন্য খুলে দিতে পারে।',
            'delete_heading' => '<strong>ব্যবহারকারী মুছুন</strong>',
            'delete_body' => '<strong>মুছুন</strong> বোতামটি <strong>FK-নিরাপদ</strong>: ব্যবহারকারী কোনো টিকিটের অনুরোধকারী হলে বা <code>users_assets</code>-এ তাঁর কোনো সারি থাকলে এটি প্রত্যাখ্যান করে, এবং একটি স্পষ্ট বার্তা দেয় <em>"Cannot delete: this user is the requester on N ticket(s). Reassign or close those tickets first."</em> অডিট ইতিহাস কখনো নীরবে ভেঙে যেতে পারে না।',
            'tip' => 'মোডালের সব ফিল্ডে ব্রাউজার অটোফিল বন্ধ করা আছে (পাসওয়ার্ড ফিল্ডে <code>autocomplete="new-password"</code>-সহ), যাতে এমন একটি ফর্মে বিশ্লেষকের নিজের সংরক্ষিত ক্রেডেনশিয়াল প্রস্তাব করা না হয় যার পুরো উদ্দেশ্যই <em>অন্য কারও</em> রেকর্ড তৈরি করা।',
            'groups_heading' => '<strong>গ্রুপ</strong>',
            'groups_body' => '<strong>ব্যক্তি</strong>-র পাশের <strong>গ্রুপ</strong> ট্যাবে নামযুক্ত ব্যক্তি-গ্রুপ থাকে &mdash; বিশ্লেষক ও সেলফ-সার্ভিস পোর্টাল ব্যবহারকারীরা একই গ্রুপে একসাথে। একটি গ্রুপ এখানে একবার তৈরি করে FreeITSM জুড়ে ব্যবহার করা হয়, ফলে একই তালিকা দুবার না বানিয়ে আপনি তাকে কোনো নলেজ ফোল্ডারের অ্যাক্সেস দিতে বা একটি প্রশিক্ষণ কোর্স বরাদ্দ করতে পারেন।',
            'groups_make' => 'গ্রুপ ট্যাবে <strong>যোগ</strong> দিয়ে <strong>একটি তৈরি করুন</strong>: একটি নাম, এবং একটি বিবরণ যা পূরণ করা সার্থক, কারণ পরের জনকে বুঝতে হবে গ্রুপটি কীসের জন্য।',
            'groups_add' => 'খুঁজে <strong>ব্যক্তি যোগ করুন</strong> &mdash; এটি বিশ্লেষক ও পোর্টাল ব্যবহারকারী একসাথে খুঁজে দেয়, তাই কে কোন ধরনের তা আপনার জানার দরকার নেই।',
            'groups_expiry' => 'অ্যাক্সেস অস্থায়ী হলে <strong>সদস্যপদে একটি শেষ তারিখ দিন</strong>। দুই সপ্তাহের জন্য সাইটে আসা তিনজন ইঞ্জিনিয়ার শেষ দিনসহ ঢোকেন এবং সেই দিন পেরোলে নিজে থেকেই গ্রুপ থেকে বেরিয়ে যান। মেয়াদোত্তীর্ণ সদস্যপদ তালিকায় থাকে, মেয়াদোত্তীর্ণ চিহ্নিত হয়ে, যাতে কার অ্যাক্সেস ছিল এবং কত দিন পর্যন্ত তা এখনো দেখা যায়।',
            'groups_uses' => '<strong>গ্রুপ কীসের জন্য ভালো:</strong> নলেজ ফোল্ডারে অ্যাক্সেস দেওয়া, এবং একসাথে একদল ব্যক্তিকে LMS প্রশিক্ষণ বরাদ্দ করা। সদস্যপদের পরিবর্তন সাথে সাথে কার্যকর হয় &mdash; পরে নতুন করে প্রয়োগ করার কিছু নেই।',
            'groups_admin' => '<strong>টিকিট মডিউল থাকা যে কেউ গ্রুপ দেখতে পান; শুধু অ্যাডমিনিস্ট্রেটর একটি বদলাতে পারেন।</strong> কাউকে গ্রুপে যোগ করলে তিনি সীমাবদ্ধ নলেজ ফোল্ডারেরও অ্যাক্সেস পেতে পারেন, তাই এটি অ্যাক্সেস প্রদান, নথি গোছানোর কাজ নয়।',
        ],
        'dash' => [
            'heading' => 'ড্যাশবোর্ড',
            'intro' => 'টিকিট ড্যাশবোর্ড কাস্টমাইজযোগ্য Chart.js উইজেট দিয়ে এক নজরে বিশ্লেষণ দেয়। প্রতিটি বিশ্লেষকের নিজস্ব ড্যাশবোর্ড লেআউট আছে, তাই আপনি আপনার ভূমিকার জন্য গুরুত্বপূর্ণ মেট্রিকে মনোযোগ দিতে পারেন &mdash; তা ব্যক্তিগত কাজের চাপ, দলের থ্রুপুট বা SLA সম্মতি যা-ই হোক।',
            'step1' => '<strong>লাইব্রেরি খুলুন</strong> &mdash; এডিটিং মোডে ঢুকতে ড্যাশবোর্ড সম্পাদনা ক্লিক করুন, তারপর উইজেট লাইব্রেরি ব্রাউজ করুন। তৈরি করা উইজেট থেকে বেছে নিন, অথবা একটি চার্টের ধরন ও যে ডেটা প্রপার্টি একত্র করা হবে তা বেছে নিজের উইজেট বানান।',
            'step2' => '<strong>উইজেট যোগ করুন</strong> &mdash; লাইব্রেরির যেকোনো উইজেটে + বোতামে ক্লিক করে এটি আপনার ড্যাশবোর্ডে যোগ করুন। এটি অবিলম্বে উপস্থিত হয় এবং আপনার টিকিট ডেটাবেস থেকে লাইভ ডেটা দেখানো শুরু করে।',
            'step3' => '<strong>কনফিগার করুন</strong> &mdash; যেকোনো উইজেটের কগ আইকনে ক্লিক করে তার শিরোনাম, চার্টের ধরন (বার, পাই, ডোনাট, লাইন, স্ট্যাকড বার, মাল্টি-লাইন), তারিখের পরিসর ফিল্টার, বিভাগ ফিল্টার এবং সময় গ্রুপিং (দৈনিক, সাপ্তাহিক, মাসিক) কাস্টমাইজ করুন।',
            'step4' => '<strong>সাজান</strong> &mdash; উইজেটগুলোর ক্রম বদলাতে ড্র্যাগ অ্যান্ড ড্রপ করুন। আপনার লেআউট প্রতি বিশ্লেষকের জন্য সংরক্ষিত হয়, তাই সেশন জুড়ে থেকে যায়।',
            'examples' => 'সাধারণ উইজেটের উদাহরণ: <strong>স্ট্যাটাস অনুযায়ী টিকিট</strong> (খোলা বনাম সমাধান হওয়া বনাম বন্ধ দেখানো ডোনাট চার্ট), <strong>অগ্রাধিকার অনুযায়ী টিকিট</strong> (তীব্রতা অনুযায়ী পরিমাণের বার চার্ট), <strong>সাপ্তাহিক পরিমাণ</strong> (সময়ের সাথে নতুন টিকিট ট্র্যাক করা লাইন চার্ট), এবং <strong>বিশ্লেষকের কাজের চাপ</strong> (প্রতিটি বিশ্লেষকের সক্রিয় টিকিট দেখানো স্ট্যাকড বার)।',
            'tip' => 'বর্তমান কার্যকারিতাকে আগের সময়ের সাথে তুলনা করতে প্রতিটি উইজেটে তারিখের পরিসর ফিল্টার ব্যবহার করুন। যেমন, "এই মাস বনাম গত মাস" ভিউ টিকিটের পরিমাণের প্রবণতা আগেভাগে ধরতে সাহায্য করে।',
        ],
        'cal_rota' => [
            'heading' => 'ক্যালেন্ডার &amp; রোটা',
            'intro' => 'দুটি সময়সূচি টুল আপনার দলকে গোছানো রাখে: সময়ের সাথে কাজের চাপ দেখানো একটি টিকিট ক্যালেন্ডার, এবং শিফট ও অন-কল প্রাপ্যতা পরিচালনার জন্য একটি স্টাফ রোটা।',
            'cal_heading' => '<strong>ক্যালেন্ডার ভিউ</strong>',
            'cal_body' => 'ক্যালেন্ডার আপনার সময়সূচিতে রাখা প্রতিটি টিকিট &mdash; <strong>কাজ নির্ধারণ</strong> দিয়ে, যা টিকিটেই এবং ইনবক্সের রাইট-ক্লিক মেনুতে আছে &mdash; তার নির্ধারিত সময়ে একটি রঙিন ব্লক হিসেবে আঁকে, নির্দিষ্ট এক ঘণ্টা নয়, তার <strong>প্রকৃত দৈর্ঘ্যে</strong>। লাল ব্লক <em>উচ্চ</em> অগ্রাধিকারের, সবুজ <em>নিম্ন</em>, আর নীল বাকি সব। নেভিগেট করতে <em>আজ</em>, <em>&lt;</em> / <em>&gt;</em> শেভরন এবং <strong>মাস / সপ্তাহ / দিন</strong> টগল ব্যবহার করুন।',
            'cal_scope' => '<strong>আমার বা সবার।</strong> ক্যালেন্ডার আপনার নিজের নির্ধারিত কাজে খোলে, ভিউ বোতামের পাশে একটি <strong>সবাই</strong> সুইচসহ; আপনার পছন্দ মনে রাখা হয়। সবার মোডে প্রতিটি টিকিটে <strong>মালিকের জন্য একটি রঙ</strong> থাকে, পর্দায় সত্যিই যাঁরা আছেন তাঁদের নাম দেওয়া একটি লেজেন্ডসহ, আর টিকিটের উপর হোভার করলে চোখ না সরিয়েই জানা যায় এটি কার। কারও কাছ থেকে কিছু লুকানো হয় না &mdash; এগুলো সেই একই টিকিট যা ইনবক্স আগে থেকেই তালিকাভুক্ত করে।',
            'cal_edit' => '<strong>কাজ নতুন করে সাজানো।</strong> একটি টিকিট অন্য দিনে বা সময়ে <strong>টেনে নিন</strong>: মাস ভিউতে এটি নিজের সময় রাখে, আর সপ্তাহ ও দিন ভিউতে যে সময়ে ছাড়বেন সেটি নেয়, নিকটতম পনেরো মিনিটে মিলিয়ে। এর দৈর্ঘ্য কখনো বদলায় না &mdash; টানা বলে <em>তখন শুরু করুন</em>, <em>আরও দীর্ঘ করুন</em> নয়। অথবা খুলতে <strong>টিকিটে ক্লিক করুন</strong>, যেখানে তারিখ, সময়, সময়কাল ও সারাদিন সেটিং বদলাতে পারেন, বা সময়সূচি পুরোপুরি মুছে দিতে পারেন। ক্যালেন্ডার <strong>কয়েক সেকেন্ড পরপর নিজেই রিফ্রেশ হয়</strong>, তাই কোনো সহকর্মী কিছু নির্ধারণ করলে আপনি রিলোড না করেই তা দেখেন &mdash; আর আপনি কোনো টিকিট খুলে রাখলে বা টানার মাঝখানে থাকলে এটি থেমে থাকে।',
            'cal_month' => '<strong>মাস ভিউ</strong> &mdash; সাধারণ ৬ সারির গ্রিড, উপরে সপ্তাহের দিনের হেডার স্ট্রিপসহ; প্রতিটি দিনের ঘরে শুরুর সময়সহ সর্বোচ্চ তিনটি টিকিট পিল দেখায়, সাথে একটি <em>+N আরও</em> লিঙ্ক যা আপনাকে সেই তারিখের দিন ভিউতে নিয়ে যায়। আজ হাইলাইট করা থাকে।',
            'cal_week' => '<strong>সপ্তাহ ভিউ</strong> &mdash; ২৪ ঘণ্টার উল্লম্ব টাইমলাইনের উপর দিয়ে উপরে সোম&ndash;রবি। টিকিট তার নির্ধারিত দৈর্ঘ্যে আঁকা হয়, তাই ১৫ মিনিটের কাজ আর বিকেলভর পুনর্নির্মাণ আলাদা দেখায়। সারাদিনের টিকিট পুরো কলাম গিলে না ফেলে তার দিনের উপরে একটি সরু বার হয়ে থাকে। আজকের কলাম হাইলাইট করা থাকে; ঘণ্টার গ্রিড স্ক্রল করলেও সপ্তাহের দিনের হেডার স্থির থাকে।',
            'cal_day' => '<strong>দিন ভিউ</strong> &mdash; বেছে নেওয়া দিনের জন্য একটি লম্বা কলাম, একই ২৪ ঘণ্টার টাইমলাইনসহ। টিকিট বড় ব্লক হিসেবে আঁকা হয়, <code>ticket_number &mdash; subject</code> ও শুরুর সময় দেখিয়ে; এর বিস্তারিত খুলতে বা কখন হবে তা বদলাতে একটিতে ক্লিক করুন।',
            'rota_heading' => '<strong>স্টাফ রোটা</strong>',
            'rota_body' => 'রোটা পৃষ্ঠা টিম লিড ও ম্যানেজারদের সপ্তাহ জুড়ে বিশ্লেষকদের শিফট নির্ধারণ করতে দেয়। স্ট্যান্ডার্ড কাজের সময় ঠিক করুন, অন-কল সময়কাল বরাদ্দ করুন, এবং ছুটি বা অনুপস্থিতি চিহ্নিত করুন যাতে দল সবসময় জানে কে উপলব্ধ।',
            'rota_step1' => '<strong>রোটা গ্রিড দেখুন</strong> &mdash; রোটা একদিকে বিশ্লেষক ও অন্যদিকে দিন দেখায়, শিফট ব্লক এক নজরে কভারেজ দেখিয়ে।',
            'rota_step2' => '<strong>শিফট যোগ বা সম্পাদনা করুন</strong> &mdash; শিফটের ধরন (যেমন Early, Late, Night, On-Call) নির্ধারণ করতে একটি ঘরে ক্লিক করুন। পরিবর্তন সাথে সাথে সংরক্ষিত হয়।',
            'rota_step3' => '<strong>আগে থেকে পরিকল্পনা করুন</strong> &mdash; আগেভাগে রোটা বানাতে সপ্তাহ ধরে সামনে এগোন। এতে জানা ব্যস্ত সময়, ছুটি বা প্রশিক্ষণের দিনে পর্যাপ্ত কভারেজ নিশ্চিত হয়।',
            'rota_step4' => '<strong>একসাথে কয়েকটি ঘর পূরণ করুন</strong> &mdash; একটি ঘরে <strong>রাইট-ক্লিক</strong> করে <em>কপি</em> বেছে নিন তার শিফট তুলে নিতে, তারপর অন্যটিতে রাইট-ক্লিক করে <em>পেস্ট</em> করুন। একাধিক ঘরের জন্য, তাদের একটি ব্লকের উপর <strong>টেনে নিন</strong> (বা একটি একটি করে ctrl-ক্লিক করুন) এবং পুরোটায় পেস্ট করুন। একটি <strong>দিনের হেডিং</strong>-এ হোভার করলে সেই পুরো দিন জ্বলে ওঠে, আর একটি <strong>বিশ্লেষকের নামে</strong> হোভার করলে তাঁর পুরো সপ্তাহ &mdash; যেকোনোটিতে রাইট-ক্লিক করে পুরোটায় পেস্ট করুন। কিছু ঘরে আগে থেকেই শিফট থাকলে মেনু সহজ ভাষায় দুটি পথই দেয় &mdash; <em>৭টিতেই পেস্ট</em> এবং <em>৬টি ফাঁকা ঘরে পেস্ট</em> &mdash; যাতে আপনি পরে নয়, কাজ করার আগেই বেছে নিতে পারেন। ওভাররাইট করতে নিশ্চিত করতে হয় এবং কতগুলো শিফট বদলাচ্ছে তা বলা হয়; ফাঁক পূরণ এমনিই হয়ে যায়, কারণ কিছু হারায় না। একই মেনুগুলো একটি দিন, সপ্তাহ বা নির্বাচনও <strong>মুছে</strong> দেবে, এবারও কতগুলো শিফট সরবে তা জানিয়ে।',
            'rota_step5' => '<strong>একজনের জন্য পুরো একটি দিন বা পুরো সপ্তাহ কপি করুন</strong> &mdash; সেই দিনের প্রতিটি শিফট তুলতে একটি <strong>দিনের হেডিং</strong>-এ রাইট-ক্লিক করে <em>কপি</em> বেছে নিন, অথবা তাঁর পুরো সপ্তাহ তুলতে একটি <strong>বিশ্লেষকের নামে</strong>। অন্য দিনে বা অন্য বিশ্লেষকের উপর পেস্ট করলে সেটি মিলে যায়: কপিতে যে শিফট ছিল না তা মুছে যায়, ফলে আপনি দুটির মিশ্রণ নয়, যে দিনটি কপি করেছেন সেটিই পান। একটি দিন শুধু অন্য দিনে এবং একজন বিশ্লেষক শুধু অন্য বিশ্লেষকে পেস্ট করা যায় &mdash; একটি দিন হলো <em>প্রতি ব্যক্তির</em> একটি শিফট আর একটি সপ্তাহ <em>প্রতি দিনের</em> একটি শিফট, তাই একটিকে অন্যটির উপর বসানোর কোনো যুক্তিসংগত উপায় নেই। চেষ্টা করলে মেনু তা বলে দেয়, এবং বদলে কোথায় যেতে পারে তাও বলে।',
            'rota_step6' => '<strong>পুরো একটি সপ্তাহ কপি করুন</strong> &mdash; উপরে ডানদিকের <strong>সপ্তাহ কপি</strong> ও <strong>সপ্তাহ পেস্ট</strong> আপনি যে সপ্তাহ দেখছেন তার প্রতিটি শিফট তুলে অন্যটিতে বসায়, যা পুনরাবৃত্ত রোটা বানানোর দ্রুততম উপায়। পেস্ট লক্ষ্য সপ্তাহকে <em>প্রতিস্থাপন</em> করে, তাই নিশ্চিতকরণে বলা হয় কতগুলো এন্ট্রি সরতে চলেছে। এটি শুধু সেই দিন ও ব্যক্তিদেরই ছোঁয় যাঁদের গ্রিড সত্যিই আপনাকে দেখাচ্ছে।',
            'tip' => 'কার্যকর সক্ষমতা পরিকল্পনার জন্য ক্যালেন্ডার ও রোটা একসাথে ব্যবহার করুন। ক্যালেন্ডারে প্রতি সোমবার সকালে টিকিটের উল্লম্ফন দেখা গেলে নিশ্চিত করুন ওই স্লটে রোটায় বাড়তি কভারেজ নির্ধারিত আছে।',
        ],
        'settings' => [
            'heading' => 'সেটিংস',
            'intro' => 'সেটিংস পেজে আপনি আপনার টিকিটিং সিস্টেমের মূল উপাদানগুলো কনফিগার করেন। সব লুকআপ ভ্যালু, SLA টার্গেট, ইমেল ইন্টিগ্রেশন এবং কাস্টম ফিল্ড এখান থেকেই পরিচালিত হয়।',
            'sla_callout_title' => 'SLA ব্যবস্থাপনা &mdash; পূর্ণ গাইড',
            'sla_callout_body' => 'কনফিগারযোগ্য অপশন, বিজনেস ক্যালেন্ডার, পজ স্ট্যাটাস, ব্রিচ নোটিফিকেশন, ক্রন জব সেটআপ, এবং একক-টাইমজোন ও ক্রস-টাইমজোন দলের জন্য বাস্তব উদাহরণ। নিজস্ব পেজ পাওয়ার মতো যথেষ্ট বিস্তারিত।',
            'card_dept_title' => 'বিভাগ',
            'card_dept_body' => 'IT, HR ও Finance-এর মতো বিভাগ তৈরি করুন। প্রতিটি বিভাগ ইনবক্সে একটি ফোল্ডার এবং ড্যাশবোর্ডে একটি ফিল্টার হয়ে যায়',
            'card_types_title' => 'টিকিটের ধরন',
            'card_types_body' => 'আপনার ডেস্ক যেসব ধরনের অনুরোধ সামলায় তা ঠিক করুন: ইনসিডেন্ট, সার্ভিস রিকোয়েস্ট, প্রবলেম, চেঞ্জ। ধরন অ্যানালিস্টদের কাজ শ্রেণিবদ্ধ করতে সাহায্য করে',
            'card_priorities_title' => 'অগ্রাধিকার',
            'card_priorities_body' => 'নাম, রঙ ও ক্রম দিয়ে অগ্রাধিকারের স্তর ঠিক করুন। প্রতিটি অগ্রাধিকার সাড়া ও সমাধানের জন্য একটি SLA টার্গেটের সাথে যুক্ত থাকে',
            'card_statuses_title' => 'স্ট্যাটাস',
            'card_statuses_body' => 'টিকিটের লাইফসাইকেলের ধাপগুলো নিজের মতো করুন। ডিফল্ট স্ট্যাটাসের মধ্যে আছে New, Open, In Progress, Pending, Resolved এবং Closed',
            'card_categories_title' => 'ক্যাটাগরি',
            'card_categories_body' => 'প্রযুক্তিগত ক্ষেত্র অনুযায়ী টিকিট সাজান: হার্ডওয়্যার, সফটওয়্যার, নেটওয়ার্ক, অ্যাক্সেস। ক্যাটাগরি রিপোর্টিংয়ের বিভাজন চালায়',
            'card_sla_title' => 'SLA টার্গেট',
            'card_sla_body' => 'প্রতিটি অগ্রাধিকারের জন্য সাড়া ও সমাধানের সময়ের টার্গেট ঠিক করুন। SLA টাইমার টিকিটে দেখা যায় এবং ব্রিচ সতর্কতা চালায়',
            'card_email_title' => 'ইমেল ইমপোর্ট',
            'card_email_body' => 'ইমেলকে স্বয়ংক্রিয়ভাবে নতুন টিকিট হিসেবে ইমপোর্ট করতে একটি মেইলবক্স (Exchange, Microsoft 365) সংযুক্ত করুন। উত্তর বিদ্যমান টিকিটেই থ্রেড হয়ে যুক্ত হয়',
            'card_custom_title' => 'কাস্টম ফিল্ড',
            'card_custom_body' => 'ডিফল্ট ফিল্ডে যে তথ্য ধরা যায় না কিন্তু আপনার প্রতিষ্ঠানের দরকার, তার জন্য টিকিটে নিজের ফিল্ড যোগ করুন',
            'card_templates_title' => 'ইমেল টেমপ্লেট',
            'card_templates_body' => 'টিকিট তৈরি, হালনাগাদ বা সমাধান হলে এবং CSAT সমীক্ষার জন্য এন্ড ইউজারদের পাঠানো নোটিফিকেশন টেমপ্লেট কনফিগার করুন। [requester_name] ও [csat_link]-এর মতো মার্জ কোড বসান',
            'card_checklists_title' => 'চেকলিস্ট',
            'card_checklists_body' => 'কেউ এমন একটি টিকিট বন্ধ করলে যেটিতে বাধ্যতামূলক চেকলিস্ট স্টেপ বাকি আছে, তখন কী হবে তা ঠিক করুন: <strong>সতর্ক করুন</strong> এবং কোন স্টেপ বাকি ও কে বন্ধ করেছেন তা উল্লেখ করে একটি অভ্যন্তরীণ নোট রাখুন, অথবা সেগুলো শেষ না হওয়া পর্যন্ত বন্ধ করা <strong>আটকে দিন</strong>। টিকিট যেখানেই বন্ধ করা যায় সেখানেই প্রযোজ্য - বাল্ক অ্যাকশন, REST API এবং ওয়ার্কফ্লো অটোমেশনসহ',
            'card_custom_fields_title' => 'কাস্টম ফিল্ড',
            'card_custom_fields_body' => 'এক ধরনের টিকিটের প্রয়োজনীয় বাড়তি তথ্য ঠিক করুন - টেক্সট, সংখ্যা, তারিখ, হ্যাঁ / না, আপনার নিজের অপশনের ড্রপডাউন, ওয়েব বা ইমেল ঠিকানা - এবং প্রতিটি ফিল্ড কিছু টিকিটের ধরনের সাথে বা সবগুলোর সাথে যুক্ত করুন। প্রতিটি ফিল্ড ঠিক করে সেটি <strong>টিকিট লগ করার সময়</strong> (নতুন টিকিট ফর্ম, REST API এবং চাইলে পোর্টাল), <strong>বন্ধ করার আগে</strong> (বাধ্যতামূলক ফিল্ড নিয়ম অনুযায়ী), নাকি দুই সময়েই পূরণ করতে হবে, এবং পোর্টালে <strong>অনুরোধকারীকে জিজ্ঞাসা করা হবে</strong> কিনা - যেখানে এটি জিজ্ঞাসা করা বিষয় বদলালে একটি টিকিটের ধরন বাছাইয়ের অপশন দেখা যায়। উত্তরগুলো টিকিটের প্রপার্টি প্যানেলে ও তার ইতিহাসে দেখা যায়। টিকিটের ধরন বদলালে নতুন ধরনে যেসব উত্তর নেই সেগুলো লুকিয়ে যায়, কখনো মুছে যায় না',
            'card_mandatory_title' => 'বাধ্যতামূলক ফিল্ড',
            'card_mandatory_body' => 'টিকিট বন্ধ করার আগে যেসব ফিল্ড পূরণ করতে হবে সেগুলোতে টিক দিন - ক্যাটাগরি, রেজোলিউশন কোড, মালিক ইত্যাদি। তারপর কোনো ফিল্ড খালি রেখে কেউ টিকিট বন্ধ করলে কী হবে তা বেছে নিন: <strong>সতর্ক করুন</strong>, সার্ভিস ডেলিভারি ম্যানেজারের মতো কাউকে <strong>সতর্ক করে ইমেল পাঠান</strong>, অথবা বন্ধ করা <strong>প্রত্যাখ্যান করুন</strong>। আলাদা একটি সুইচ এটি টিকিটে অভ্যন্তরীণ নোট হিসেবে রেকর্ড করে। কোনো কোম্পানির জন্য বন্ধ করা ফিল্ড কখনো বাধ্যতামূলক হয় না, এবং টিকিট মার্জ করলে এটি কখনো চালু হয় না। টিকিট যেখানেই বন্ধ করা যায় সেখানেই প্রযোজ্য - বাল্ক অ্যাকশন, REST API এবং ওয়ার্কফ্লো অটোমেশনসহ',
            'card_cleanup_title' => 'রিপ্লাই ক্লিনআপ AI',
            'card_cleanup_body' => 'রিপ্লাই এডিটরের ✨ ক্লিনআপ বোতামের জন্য Anthropic কী + মডেল + টোন। সূক্ষ্ম বিলিংয়ের জন্য অন্য AI ফিচারের থেকে আলাদা কী',
            'card_csat_title' => 'CSAT',
            'card_csat_body' => 'পাঠানোর মোড (বন্ধ / স্বয়ংক্রিয় / ম্যানুয়াল), বিলম্ব, প্রতি টিকিটে একবার সুরক্ষা, স্কেল (তারা বা ইমোজি)। পুরো প্রক্রিয়ার জন্য ৬ নম্বর অংশ দেখুন',
            'email_heading' => '<strong>ইমেল ইমপোর্ট বিস্তারিত</strong>',
            'email_body' => 'ইমেল ইমপোর্ট ফিচার আপনার শেয়ার্ড মেইলবক্সের সাথে সংযুক্ত হয়ে নতুন বার্তাগুলোকে টিকিট হিসেবে নিয়ে আসে। কোনো এন্ড ইউজার আপনার সাপোর্ট ঠিকানায় (যেমন support@yourcompany.com) ইমেল পাঠালে FreeITSM ইমেলের বিষয়কে শিরোনাম এবং ইমেলের মূল অংশকে বিবরণ করে একটি টিকিট তৈরি করে। প্রেরক কোনো নোটিফিকেশন ইমেলের উত্তর দিলে নতুন ডুপ্লিকেট তৈরি না করে উত্তরটি বিদ্যমান টিকিটেই থ্রেড হয়ে যুক্ত হয়।',
            'email_step1' => '<strong>মেইলবক্স কনফিগার করুন</strong> &mdash; সেটিংসে গিয়ে আপনার Exchange বা Microsoft 365 ক্রেডেনশিয়াল দিন। নিরাপদ, পাসওয়ার্ডবিহীন সংযোগের জন্য OAuth অথেনটিকেশন সমর্থিত।',
            'email_step2' => '<strong>পোলিং ব্যবধান ঠিক করুন</strong> &mdash; FreeITSM কত ঘন ঘন মেইলবক্সে নতুন বার্তা খুঁজবে তা বেছে নিন। ব্যবধান কম হলে টিকিট দ্রুত তৈরি হয়।',
            'email_step3' => '<strong>ডিফল্ট ম্যাপ করুন</strong> &mdash; ইমেল থেকে তৈরি টিকিটের জন্য ডিফল্ট বিভাগ, ধরন ও অগ্রাধিকার ঠিক করুন। ইমপোর্টের পর অ্যানালিস্টরা এগুলো বদলাতে পারেন।',
            'tip' => 'এন্ড ইউজারদের সব যোগাযোগে পেশাদার ও সামঞ্জস্যপূর্ণ সুর বজায় রাখতে ইমেল টেমপ্লেট ব্যবহার করুন। টেমপ্লেটে টিকিটের রেফারেন্স, অনুরোধকারীর নাম, অ্যানালিস্টের নাম এবং স্ট্যাটাসের জন্য ডায়নামিক প্লেসহোল্ডার ব্যবহার করা যায়।',
            'closemsg_heading' => '<strong>টিকিট বন্ধ করার সময় একবারের বার্তা</strong>',
            'closemsg_body' => '<code>[ticket_closed_message]</code> বসান একটি সক্রিয় <strong>Ticket closed</strong> টেমপ্লেটের যেকোনো জায়গায়, তারপর থেকে কোনো টিকিটকে বন্ধ স্ট্যাটাসে নিলে অ্যানালিস্টের কাছে একটি বাক্য চাওয়া হবে - <em>&ldquo;বাড়তি চার্জারটি আপনার ডেস্কে আছে&rdquo;</em>, <em>&ldquo;ফোনে যেমন ঠিক হয়েছিল সেভাবেই বন্ধ করা হলো&rdquo;</em>। তাঁরা যা লিখবেন তা ঠিক সেখানেই বসবে যেখানে আপনি প্লেসহোল্ডার রেখেছেন, ফলে আশপাশের শব্দচয়নের নিয়ন্ত্রণ আপনার হাতেই থাকে। এটি কোনো সেটিং নয় এবং কিছুই এটি জমা রাখে না: একটি নোট, একটি টিকিট, একটি ইমেল। কিছু না লিখলে লাইনটি সরলভাবে থাকেই না - কোনো ফাঁক বা বাড়তি যতিচিহ্ন থাকে না।',
            'closemsg_note' => '<strong>টেমপ্লেটে প্লেসহোল্ডারটি সত্যিই থাকলেই কেবল প্রম্পট আসে।</strong> এটি না থাকলে অ্যানালিস্টের লেখা যেকোনো কিছু নীরবে ফেলে দেওয়া হতো, আর যে ডেস্ক এটি চায় না তার প্রতিটি টিকিট বন্ধ করায় একটি করে বাড়তি ক্লিক যোগ হতো। তাই আপনি কনফিগার করলে এটি নিজে থেকে চালু হয়, আর না করলে পথ থেকে সরে থাকে।',
            'cat_heading' => '<strong>ক্যাটাগরি, এবং তার পাশের দুটি ফিল্ড</strong>',
            'cat_body' => 'টিকিটের <em>ধরন</em> বলে এটি কী জাতীয় জিনিস; <em>ক্যাটাগরি</em> বলে এটি কী নিয়ে। তালিকাটি <strong>সেটিংস &rarr; ক্যাটাগরি</strong>-তে বানান, সাথে সেই সুইচগুলোও, যেগুলো ঠিক করে এর কিছু আদৌ টিকিটে দেখা যাবে কিনা।',
            'cat_card_one_title' => 'ক্যাটাগরি',
            'cat_card_one_body' => 'টিকিট তোলার সময় বেছে নেওয়া, অর্থাৎ যা হিসেবে এটি রিপোর্ট করা হয়েছিল। একটি টিকিটের ঠিক একটিই থাকে, তাই আপনার ক্যাটাগরির রিপোর্টের যোগফল সবসময় আপনার প্রকৃত টিকিটের সংখ্যার সমান হয়।',
            'cat_card_close_title' => 'বন্ধের সময়ের ক্যাটাগরি',
            'cat_card_close_body' => 'টিকিট শেষ হলে একই তালিকা আবার জিজ্ঞাসা করা হয়। সাধারণত অ্যানালিস্ট শুধু নিশ্চিত করেন &mdash; প্রথম অনুমান ভুল হওয়া টিকিটগুলোতেই এর মূল্য, আর তা থেকেই জানা যায় আপনার সাঁইত্রিশটি "প্রিন্টার সমস্যা"-র মধ্যে বারোটি আসলে নেটওয়ার্কের ছিল।',
            'cat_card_res_title' => 'রেজোলিউশন কোড',
            'cat_card_res_body' => 'টিকিট কী নিয়ে ছিল তা নয়, কীভাবে শেষ হলো তা &mdash; "রিমোটে ঠিক করা হয়েছে", "প্রশিক্ষণ দেওয়া হয়েছে", "কোনো ত্রুটি পাওয়া যায়নি"। শুরু থেকেই দশটি যুক্তিসঙ্গত কোড আছে এবং সবগুলো আপনি বদলাতে পারেন।',
            'cat_rule_off' => '<strong>তিনটিই শুরুতে বন্ধ থাকে।</strong> আগে আপনার তালিকা বানান, তারপর যেগুলো চান সেগুলো চালু করুন। প্রতিটি কোম্পানির জন্য আলাদাভাবে ঠিক করা যায়।',
            'cat_rule_levels' => 'ক্যাটাগরির সাব-ক্যাটাগরি থাকতে পারে সর্বোচ্চ তিন স্তর পর্যন্ত, এবং কোনো স্তরই বাধ্যতামূলক নয়।',
            'cat_rule_type' => 'একটি ক্যাটাগরি একটি টিকিটের ধরনের সাথে বাঁধা যায়, যেমন "ব্যবহারকারী অনবোর্ডিং" শুধু সার্ভিস রিকোয়েস্টেই দেওয়া হবে। বাঁধনটি শীর্ষ স্তরের ক্যাটাগরির, আর তার সাব-ক্যাটাগরিগুলো তা অনুসরণ করে।',
            'cat_rule_typechange' => '<strong>টিকিটের ধরন বদলালে পুরোনো ধরনের সাথে যুক্ত ক্যাটাগরি মুছে যায়</strong>, এবং স্ক্রিনে তা জানানো হয়। কোনো ধরনের সাথে না বাঁধা ক্যাটাগরি বদলের পরেও থেকে যায়।',
            'cat_rule_portal' => 'সেলফ-সার্ভিস পোর্টালে কোনো ক্যাটাগরি দিতে <em>Customers can pick this</em>-এ টিক দিন। অনুরোধকারীরা সহজ ভাষায় একটি ছোট তালিকা দেখেন, আর অ্যানালিস্টরা পুরো ট্রি দেখেন।',
            'cat_rule_retire' => 'কোনো ক্যাটাগরি অবসর দিতে সেটি বন্ধ করুন &mdash; যেসব টিকিটে এটি আছে সেগুলোতে থাকে, কিন্তু নতুন টিকিটে আর দেওয়া হয় না। মুছে ফেলার চেয়ে এটি প্রায় সবসময়ই ভালো, কারণ কিছু এখনো এটি ব্যবহার করলে মোছা প্রত্যাখ্যান করা হয়।',
            'cat_rule_report' => 'তিনটিই টিকিট ড্যাশবোর্ডে চার্ট করা যায়। দুটি ক্যাটাগরি চার্ট শীর্ষ স্তর পর্যন্ত জমা হয়, এবং কিছু ঠিক না করা টিকিট লুকিয়ে না রেখে <em>Not categorised</em> হিসেবে গোনা হয়।',
            'cat_tip' => 'কোথা থেকে শুরু করবেন নিশ্চিত না হলে ক্যাটাগরি খালি রেখে শুধু <strong>রেজোলিউশন কোড</strong> চালু করুন। আপনার কাজ সবচেয়ে দ্রুত বদলে দেয় এই ফিল্ডই &mdash; আপনার পাঁচ ভাগের এক ভাগ টিকিট "প্রশিক্ষণ দেওয়া হয়েছে" হয়ে ফিরলে সেটি ডকুমেন্টেশনের সমস্যা, IT-র নয়।',
