            'ai_body' => 'একটি কাঁচা খসড়া (বা শুধু বুলেট পয়েন্ট) লিখে <strong>✨ ক্লিনআপ</strong> ক্লিক করুন &mdash; Claude সেটিকে সম্বোধন, ব্যাকরণ সংশোধন ও সমাপনীসহ একটি যথাযথ ইমেল হিসেবে নতুন করে লেখে। ৩০ সেকেন্ডের জন্য Undo লিঙ্ক দেখা যায়।',
            'feedback_title' => 'মতামত চান',
            'feedback_body' => 'টিকিট বন্ধ হলে অনুরোধকারীদের স্বয়ংক্রিয়ভাবে সমীক্ষা পাঠাতে <strong>সেটিংস &rarr; CSAT</strong>-এ CSAT চালু করুন। প্রতিটি অ্যানালিস্টের প্রবণতা <code>tickets/csat/</code>-এ থাকে &mdash; ডেভেলপমেন্ট নিয়ে আলোচনার জন্য সোনার খনি।',
