            'switcher_body' => 'হেডারে একটি <strong>কোম্পানি সুইচার</strong> দেখা যায়। এটি ঠিক করে আপনি কোন কোম্পানিতে কাজ করছেন &mdash; টিকিট তালিকা, ফোল্ডার ও সংখ্যা শুধু সেই কোম্পানির দেখায়, এবং আপনি যে টিকিট তৈরি করেন তা সেই কোম্পানিতেই জমা হয়। একাধিক কোম্পানিতে অ্যাক্সেস থাকা স্টাফ এদের মধ্যে বদলাতে পারেন; বর্তমানটি সবসময় দেখানো হয় যাতে ভুল প্রসঙ্গে উত্তর দিয়ে না ফেলেন। কোম্পানিগুলো নিজে পরিচালনা করুন <strong>সিস্টেম &rarr; কোম্পানি</strong>-তে।',
            'mailboxes_heading' => 'প্রতিটি মেইলবক্স দুই ধরনের একটি &mdash; এটিই রাউটিং ঠিক করে:',
            'card_pinned_title' => 'পিন করা মেইলবক্স',
            'card_pinned_body' => 'একটি কোম্পানির জন্য নির্দিষ্ট (যেমন কোনো ক্লায়েন্টের নিজস্ব <code>itsupport@</code>)। এর <strong>সমস্ত</strong> মেইল সেই কোম্পানিতে জমা হয় &mdash; প্রেরককে বিবেচনা করা হয় না &mdash; এবং উত্তরও এখান থেকেই যায়, ফলে ক্লায়েন্ট শুরু থেকে শেষ পর্যন্ত নিজের হেল্প ডেস্কই দেখে।',
            'card_shared_title' => 'শেয়ার্ড ইনটেক মেইলবক্স',
            'card_shared_body' => 'একটি ঠিকানা যা অনেক কোম্পানিকে সেবা দেয় (যেমন কোনো প্রদানকারীর একক <code>support@theprovider.com</code>)। ঠিকানা থেকে এটি কোম্পানি বুঝতে পারে না, তাই <strong>কে ইমেলটি পাঠিয়েছে</strong> তা দেখে বের করে। বহু ক্লায়েন্টসহ প্রদানকারীর জন্য প্রস্তাবিত সেটআপ।',
            'routing_heading' => 'শেয়ার্ড-ইনটেক মেইলবক্স কীভাবে কোম্পানি বেছে নেয়',
            'routing_body' => 'প্রতিটি আগত ইমেলের জন্য এটি নিচের ধাপগুলো ক্রমানুসারে চেষ্টা করে, এবং প্রথম মিলটিই কার্যকর হয়:',
            'flow_reply' => 'টিকিটের উত্তর',
