            'flow_triage' => 'ট্রায়াজ',
            'rule_reply' => '<strong>১. বিদ্যমান টিকিটের উত্তর</strong> &mdash; রেফারেন্স দেখে শনাক্ত হলে ইমেলটি সেই টিকিটে যুক্ত হয় এবং তার কোম্পানি বজায় থাকে।',
            'rule_sender' => '<strong>২. নির্দিষ্ট প্রেরকের ঠিকানা</strong> কোনো কোম্পানির সাথে সংযুক্ত থাকলে (যেমন <code>jane@gmail.com</code> &rarr; Acme) &mdash; সেই কোম্পানি। এটি ডোমেইনের আগে যাচাই করা হয়, তাই ব্যক্তিগত/ওয়েবমেইল ঠিকানাতেও কাজ করে।',
            'rule_domain' => '<strong>৩. প্রেরকের ডোমেইন</strong> কোনো কোম্পানির সাথে সংযুক্ত থাকলে (যেমন <code>@acme.com</code>-এর যে কেউ &rarr; Acme) &mdash; সেই কোম্পানি।',
            'rule_triage' => '<strong>৪. কোনো মিল নেই</strong> &mdash; ইমেলটি হারিয়ে না গিয়ে <strong>ট্রায়াজ</strong> সারিতে যায় (নিচে দেখুন)।',
            'keys_heading' => 'ডোমেইন &amp; নির্দিষ্ট প্রেরক (সিস্টেম &rarr; কোম্পানি-তে প্রতি কোম্পানির জন্য নির্ধারিত)',
            'keys_body' => 'শেয়ার্ড-ইনটেক মেইলবক্স এই কী-গুলো দিয়ে মেলায়। প্রতিটি কোম্পানি তার মালিকানাধীন ইমেল ডোমেইনের তালিকা দেয় এবং ইচ্ছে হলে আলাদা প্রেরকের ঠিকানাও দিতে পারে।',
            'card_domains_title' => 'ইমেল ডোমেইন',
            'card_domains_body' => 'কোম্পানির মালিকানাধীন ডোমেইন (acme.com, acme.co.uk)। নিবন্ধিত ডোমেইনের যেকোনো প্রেরক সেই কোম্পানিতে রাউট হয়। একটি ডোমেইন কেবল একটি কোম্পানির হতে পারে।',
            'card_senders_title' => 'নির্দিষ্ট প্রেরক',
            'card_senders_body' => 'কোম্পানির সাথে সংযুক্ত আলাদা ঠিকানা, ডোমেইনের আগে যাচাই করা হয়। ব্যক্তিগত ঠিকানা থেকে ইমেল করা ফ্রিল্যান্সার বা ছোট ক্লায়েন্টের জন্য এটি ব্যবহার করুন।',
            'card_public_title' => 'পাবলিক প্রদানকারী',
            'card_public_body' => 'Gmail, Outlook, Yahoo এবং এ ধরনের সেবা ডোমেইন হিসেবে সংযুক্ত করা যায় না (অসংখ্য সম্পর্কহীন মানুষ এগুলো ব্যবহার করে) &mdash; এর বদলে সঠিক ঠিকানাটি নির্দিষ্ট প্রেরক হিসেবে সংযুক্ত করুন।',
            'triage_heading' => 'ট্রায়াজ সারি &mdash; নিরাপত্তা জাল',
            'triage_body' => 'শেয়ার্ড-ইনটেক ইমেল কোনো কোম্পানির সাথে না মিললে সেটি হারিয়ে না গিয়ে <strong>ট্রায়াজ</strong>-এ জমা হয় (কোম্পানি সুইচার থেকে পৌঁছানো যায়, সাথে লাইভ সংখ্যা থাকে)। প্রতিটি আইটেমে প্রেরক, ডোমেইন, বিষয় এবং কোন মেইলবক্সে এসেছে তা দেখানো হয়। এক ধাপেই এটি কোনো কোম্পানিতে জমা দিন:',
            'triage_create' => 'একটি বিদ্যমান কোম্পানি বেছে নিন, অথবা সাথে সাথে নতুন একটি তৈরি করুন।',
            'triage_assign' => 'সাধারণ ডোমেইনের ক্ষেত্রে ইচ্ছে হলে <strong>সেই ডোমেইন রাউট করুন</strong> ওই কোম্পানিতে; পাবলিক/ওয়েবমেইল ঠিকানার ক্ষেত্রে ইচ্ছে হলে <strong>সেই প্রেরককে সবসময় জমা দিন</strong> সেখানে।',
            'triage_sweep' => 'যেকোনো একটি বিকল্পই <em>সুইপ</em> করে: সেই ডোমেইন বা ঠিকানার সারিতে থাকা অন্য সব ইমেলও সরিয়ে নেয় এবং ভবিষ্যতের মেইল স্বয়ংক্রিয়ভাবে রাউট করে &mdash; ফলে একই প্রেরককে একবারই বাছাই করতে হয়।',
            'triage_tip' => 'কিছুই হারায় না। অমিল মেইল কেউ জমা না দেওয়া পর্যন্ত ট্রায়াজে অপেক্ষা করে; ইতিমধ্যে জমা না দেওয়া টিকিট ডিফল্ট কোম্পানির অধীনে দেখা যায়।',
            'test_heading' => 'চালু করার আগে রাউটিং পরীক্ষা করুন',
            'test_body' => '<strong>সিস্টেম &rarr; ইমেল রাউটিং পরীক্ষা</strong>-তে আপনি ভান করতে পারেন যে একটি ইমেল এসেছে &mdash; একটি মেইলবক্স বেছে নিন, প্রেরকের ঠিকানা লিখুন &mdash; এবং দেখুন নতুন টিকিট ঠিক কোন কোম্পানিতে যেত (অথবা ট্রায়াজে যেত) এবং কোন নিয়ম তা ঠিক করেছে। এটি কিছুই তৈরি করে না; শুধু আপনার সেটিংস পড়ে।',
            'settings_heading' => 'সেটিংস: ডিফল্টে শেয়ার্ড, যেখানে দরকার সেখানে নিজস্ব',
            'settings_body' => 'এই সেটিংসের কিছু <strong>প্রতি কোম্পানির জন্য নিজস্বভাবে</strong> বদলানো যায়; বাকিগুলো ইচ্ছাকৃতভাবে শেয়ার্ড থাকে। যেখানে কোনো সেটিং সহজ অপশন তালিকা &mdash; যেমন <strong>টিকিটের প্রকার</strong> ও <strong>উৎস</strong> &mdash; সেখানে কোনো কোম্পানির প্রসঙ্গে গেলে শেয়ার্ড ডিফল্টগুলো দেখবেন (যেগুলো ব্যবহার হয় না সেগুলো লুকাতে প্রতিটির পাশে চোখের আইকন আছে), সাথে ওই কোম্পানি নিজের জন্য যা যোগ করেছে তাও। খোলা টিকিটে কোনো অপশন ব্যবহৃত হলে তা লুকানো বা মোছা যায় না, এবং শেয়ার্ড ডিফল্টগুলো নিজে সম্পাদনা করতে হয় MSP / ডিফল্ট কোম্পানি থেকে।',
            'settings_custom_title' => 'প্রতি কোম্পানির জন্য নিজস্ব',
            'settings_custom_body' => 'টিকিটের প্রকার ও উৎস (এখন), এবং বিভাগ, SLA ও কাজের সময় (শীঘ্রই আসছে) &mdash; যেসব বিষয় এক ক্লায়েন্ট থেকে অন্য ক্লায়েন্টে সত্যিই আলাদা।',
            'settings_global_title' => 'সব কোম্পানিতে শেয়ার্ড',
            'settings_global_body' => 'স্ট্যাটাস ও অগ্রাধিকার সবখানে একই থাকে, ফলে কোম্পানি-জুড়ে রিপোর্টিং ও SLA সামঞ্জস্যপূর্ণ থাকে; আপনার দল, রোটা ও মেইলবক্সও তাই &mdash; এগুলো আপনার নিজের কার্যক্রম, কোনো ক্লায়েন্টের নয়।',
            'allview_heading' => '<strong>সব কোম্পানির জন্য একটি বোর্ড</strong>',
            'allview_body' => 'হেডারের কোম্পানি সুইচারে একটি <strong>সব কোম্পানি</strong> অপশন আছে। আপনি যে টিকিটগুলো দেখার অনুমতি পেয়েছেন সবই একটি তালিকায় আসে, প্রতিটি সারিতে তার কোম্পানির নাম থাকে &mdash; একাধিক প্রতিষ্ঠানকে সহায়তা করলে এবং কোনটি কার তা না হারিয়ে দিনের একটিমাত্র দৃশ্য চাইলে এটি কাজে লাগে।',
            'allview_card_scope_title' => 'এটি নতুন কিছু দেয় না',
            'allview_card_scope_body' => '"সব" মানে আপনি আগে থেকেই একটি একটি করে যে কোম্পানিগুলোতে পৌঁছাতে পারতেন সেগুলোই। যে বিশ্লেষক আপনার তিনটি প্রতিষ্ঠানের মধ্যে দুটিকে সহায়তা করেন তিনি ঠিক সেই দুটিই দেখেন, আর একটি কোম্পানির বিশ্লেষক সেই একটিরই দৃশ্য দেখেন।',
            'allview_card_props_title' => 'প্রতিটি প্রতিষ্ঠান আলাদা থাকে',
            'allview_card_props_body' => 'টিকিট খুললে তার প্রকার, উৎস, বিভাগ ও সমাধানের তালিকা হয় <em>সেই</em> কোম্পানির নিজেরটি &mdash; ফলে এক প্রতিষ্ঠানের বিভাগ, যা অন্যটির নেই, কখনো ভুল টিকিটে প্রয়োগ হতে পারে না।',
            'allview_card_new_title' => 'নতুন টিকিটে কোম্পানি জানতে চাওয়া হয়',
            'allview_card_new_body' => 'ধরে নেওয়ার মতো কোনো একক সক্রিয় কোম্পানি নেই, আর এই পছন্দই ঠিক করে টিকিটের নম্বর, কোন মেইলবক্স থেকে উত্তর যাবে এবং কোন SLA প্রযোজ্য হবে। আপনি বেছে নেওয়ার পর প্রকারের তালিকা পূরণ হয়।',
            'allview_rule_chip' => 'ইমেল বা পোর্টালের মাধ্যমে আসা যে টিকিট এখনো রাউট হয়নি, সেটি ডিফল্টের অধীনে না দেখিয়ে <strong>রাউট হয়নি</strong> চিহ্নিত করা হয়, যাতে ট্রায়াজের জন্য আলাদাভাবে চোখে পড়ে।',
            'allview_rule_reply' => 'উত্তর এখনো সেই মেইলবক্স থেকেই যায় যেখানে টিকিটটি এসেছিল &mdash; এটি টিকিটের সাথে চলে, ভিউয়ের সাথে নয়, তাই সম্মিলিত বোর্ড ভুল ঠিকানা থেকে পাঠাতে পারে না।',
            'allview_rule_knowledge' => 'সম্মিলিত ভিউ চালু থাকলে <strong>AI-কে জিজ্ঞাসা</strong> কেবল একটি নয়, আপনার দেখা সব কোম্পানিতে অনুসন্ধান করে। সব কোম্পানির সাথে শেয়ার করা নিবন্ধ উভয় ক্ষেত্রেই অন্তর্ভুক্ত থাকে।',
            'allview_rule_trash' => '<strong>ট্র্যাশ খালি করা কখনো একাধিক কোম্পানিতে যায় না।</strong> এটি সবসময় আপনার সর্বশেষ বেছে নেওয়া একক কোম্পানিতে প্রযোজ্য হয়, কারণ একসাথে কয়েকটি প্রতিষ্ঠানের "বিনের সবকিছু মুছুন" কথাটি কেউ বোঝাতে চায় না।',
            'allview_rule_other' => 'শুধু টিকিট তালিকা প্রসারিত হয়। অ্যাসেট, পরিবর্তন, কাজ ও CMDB এখনো একবারে একটি কোম্পানি দেখায় &mdash; সেগুলোতে কাজ করতে ওই কোম্পানিতে যান।',
            'privacy_heading' => 'প্রতিটি কোম্পানির টিকিট গোপন থাকে',
            'privacy_body' => 'কোনো কোম্পানির প্রসঙ্গে কাজ করার সময় আপনি শুধুই <strong>সেই</strong> কোম্পানির টিকিট দেখেন &mdash; তালিকায়, অনুসন্ধানে, ড্যাশবোর্ডে এবং আপনার খোলা প্রতিটি টিকিটে (এর ইমেল, সংযুক্তি, নোট ও ইতিহাসসহ)। কোনো স্টাফ সদস্য কেবল তখনই টিকিটে পৌঁছাতে পারেন যখন তাকে সেই কোম্পানির অ্যাক্সেস দেওয়া হয়েছে (প্রতিটি বিশ্লেষকের কোম্পানি আপনি সিস্টেম &rarr; বিশ্লেষক-এ বেছে নেন, অথবা সিস্টেম &rarr; দল-এ পুরো দলকে অ্যাক্সেস দেন), তাই অন্য ক্লায়েন্টের ডেটায় ঢুকে পড়ার কোনো উপায় নেই। এই পৃথকীকরণ পর্দার আড়ালে সবখানে কার্যকর, শুধু দৃষ্টি থেকে লুকানো নয়। একক-কোম্পানির ইনস্টলে এটি স্বয়ংক্রিয় ও অদৃশ্য &mdash; কোম্পানি একটিই, তাই সবকিছু স্বাভাবিকভাবে সেটিরই।',
            'tip' => 'একক-কোম্পানির ইনস্টলে এসবের কিছুই দেখা যায় না &mdash; কোম্পানি একটিই, প্রতিটি টিকিট সেটির, এবং কোনো সুইচার বা ট্রায়াজ নেই। দ্বিতীয় কোম্পানি তৈরি হলেই এই ফিচারগুলো চালু হয়।',
