            'p1' => 'সার্ভিস লেভেল অ্যাগ্রিমেন্ট (SLA) হলো একটি টিকিটে আপনার দল কত দ্রুত সাড়া দেবে এবং তা সমাধান করবে তার প্রতিশ্রুতি। FreeITSM প্রতিটি টিকিটে দুটি ঘড়ি ট্র্যাক করে: <strong>রেসপন্স</strong> (টিকিট তৈরি থেকে বিশ্লেষকের প্রথম পদক্ষেপ পর্যন্ত সময়) এবং <strong>রেজোলিউশন</strong> (টিকিট তৈরি থেকে টিকিট বন্ধ হওয়া পর্যন্ত সময়)। দুটি লক্ষ্যই অগ্রাধিকার অনুযায়ী ঠিক করা হয় &mdash; তাই P1-এর জন্য রেসপন্সে ৩০ মিনিট ও রেজোলিউশনে ৪ ঘণ্টা থাকতে পারে, আর P4-এর জন্য ৮ কর্মঘণ্টা ও ৫ কর্মদিবস।',
            'p2' => 'FreeITSM-এর SLA ইঞ্জিনের চারটি নকশাগত সিদ্ধান্ত বোঝা জরুরি:',
            'choice_business' => '<strong>কর্মঘণ্টা, ঘড়ির সময় নয়।</strong> বিকাল ৪:৩০-এ তোলা একটি P2 টিকিটের রেসপন্স লক্ষ্য ১ ঘণ্টা হলেও অফিস ৫টায় বন্ধ হলে সেটি ৫:৩০-এ ব্রিচ হয় না। ঘড়ি পরের কর্মদিবসের সকাল ৯টায় আবার চলে। বিশ্লেষকরা রাতে বাড়ি গেলে এটিই একমাত্র ন্যায্য মডেল এবং শিল্পের মান।',
            'choice_pause' => '<strong>পজ করা যায়।</strong> টিকিট "Pause SLA" চিহ্নিত কোনো স্ট্যাটাসে থাকলে (যেমন <em>Awaiting Response</em> বা <em>On Hold</em>) ঘড়ি থেমে যায়। টিকিট কাজের স্ট্যাটাসে ফিরলে ঘড়ি আবার চলে।',
            'choice_compute' => '<strong>দেখার সময় হিসাব, জমা করা নয়।</strong> আপনি যতবার দেখেন, ইঞ্জিন টিকিটের অডিট লগ থেকে SLA অবস্থা নতুন করে হিসাব করে। অসামঞ্জস্য হতে পারে এমন কোনো সংরক্ষিত কাউন্টার নেই। পরে কোনো বিজনেস ক্যালেন্ডারের সময় বদলালে, প্রতিটি পুরোনো টিকিটের SLA পরের বার দেখার সময় নতুন সময় অনুযায়ী আবার হিসাব হবে।',
            'choice_cutoff' => '<strong>কার্যকরের সীমা।</strong> অ্যাডমিন-নিয়ন্ত্রিত "Enforce SLAs from" তারিখের কারণে SLA চালু করামাত্র আপনার সিস্টেমের বিদ্যমান টিকিটগুলো হঠাৎ পূর্বপ্রভাবে ব্রিচ হয়ে যায় না। শুধু সীমার তারিখে বা তার পরে তৈরি টিকিট ট্র্যাক করা হয়।',
