            'cal_outro' => 'প্রয়োজন মতো যত খুশি ক্যালেন্ডার তৈরি করতে পারেন &mdash; প্রতি অফিসে একটি, প্রতি দলে একটি, বা বর্ধিত সময়ের VIP গ্রাহকদের জন্য একটি। এগুলো SLA লক্ষ্য ও ব্রিচ-চেক ইঞ্জিন দুটিতেই ব্যবহৃত হয়।',
