            'prio_resolution' => '<strong>রেজোলিউশন লক্ষ্য (মিনিট)</strong> &mdash; টিকিট বন্ধ হওয়া পর্যন্ত কত সময়।',
            'prio_calendar' => '<strong>ক্যালেন্ডার</strong> &mdash; এই অগ্রাধিকারের ঘড়ি কোন বিজনেস ক্যালেন্ডার অনুযায়ী চলবে। ডিফল্ট ক্যালেন্ডার ব্যবহার করতে ফাঁকা রাখুন।',
            'prio_outro' => 'দুটি লক্ষ্য ঘর ফাঁকা রাখলে সেই অগ্রাধিকারের SLA ট্র্যাকিং সম্পূর্ণ বন্ধ থাকে &mdash; "Informational" বা "Backlog"-এর মতো অগ্রাধিকারের জন্য কাজে লাগে, যেখানে সময়ের চাপ নেই।',
