            'pause_awaiting' => '<strong>Awaiting Response</strong> &mdash; গ্রাহকের কাছ থেকে তথ্য পাওনা। প্রায় সবাই এটিকে ন্যায্য পজ হিসেবে মানে।',
            'pause_vendor' => '<strong>On Hold (Vendor)</strong> &mdash; Microsoft / তৃতীয় পক্ষের সহায়তার অপেক্ষায়।',
            'pause_change' => '<strong>On Hold (Change Window)</strong> &mdash; ভবিষ্যতের রক্ষণাবেক্ষণ উইন্ডোর জন্য নির্ধারিত।',
            'pause_parts' => '<strong>On Hold (Parts)</strong> &mdash; হার্ডওয়্যার ডেলিভারির অপেক্ষায়।',
            'pause_warn' => 'সাধারণ "On Hold" স্ট্যাটাস টিকিট কঠিন হলে বা বিশ্লেষক ব্যস্ত থাকলে SLA থেকে পালানোর পথ হিসেবে অপব্যবহার হতে পারে। আপনার দলে শৃঙ্খলা থাকলে এটি ঠিক আছে। না থাকলে এটির জায়গায় ওপরের আরও নির্দিষ্ট স্ট্যাটাসগুলো ব্যবহার করুন, অথবা <strong>Watchtower</strong> ড্যাশবোর্ডের ওপর ভরসা করুন, যা ২৪ ঘণ্টার বেশি পজ থাকা টিকিটকে হলুদ সতর্কতা হিসেবে দেখায়।',
            'cutoff_heading' => '৪. কার্যকরের সীমা (<code>Enforce SLAs from</code>)',
            'cutoff_p1' => 'সবচেয়ে গুরুত্বপূর্ণ একক গ্লোবাল সেটিং। এখানে তারিখ-সময় না দেওয়া পর্যন্ত SLA ট্র্যাকিং সম্পূর্ণ বন্ধ থাকে &mdash; কোনো ঘড়ি চলে না, ইনবক্সে কোনো পিল দেখায় না, কোনো ব্রিচ ইমেইল যায় না। অতীতের তারিখ-সময় দিলে সেই বিন্দু থেকে পূর্বপ্রভাবে SLA চালু হয়। ভবিষ্যতের তারিখ-সময় দিলে চালু হওয়ার সময় নির্ধারিত হয়।',
            'cutoff_p2' => 'বেশিরভাগ দল প্রথমবার SLA চালু করার সময় এটি "এখন" করে দেয় &mdash; বিদ্যমান টিকিট SLA-পূর্ব অবস্থায় থাকে, আর সেই মুহূর্ত থেকে নতুন টিকিট ট্র্যাক হয়।',
