            'sub' => 'এগুলো ঠিক করে ব্যতিক্রমী পরিস্থিতিতে ইঞ্জিন কীভাবে সাড়া দেবে। ডিফল্টগুলো যুক্তিসংগত &mdash; নির্দিষ্ট পছন্দ থাকলেই কেবল এগুলো দেখুন।',
            'prio_heading' => 'চলমান অবস্থায় অগ্রাধিকার বদলালে',
            'prio_intro' => 'একটি P3 টিকিট মাঝপথে P1-এ উন্নীত হলে (কারণ সমস্যাটি ভাবার চেয়ে বড় বেরোলো), তিনটি যুক্তিসংগত আচরণ আছে:',
            'prio_forward' => '<strong>Forward (ডিফল্ট)</strong> &mdash; জমে থাকা কর্মমিনিট রেখে শুধু লক্ষ্য বদলানো হয়। টিকিট যদি তার ৮ ঘণ্টার P3 লক্ষ্যের ২ ঘণ্টা ব্যবহার করে থাকে, তাহলে এখন ১ ঘণ্টার P1 লক্ষ্যের বিপরীতে ২ ঘণ্টা ব্যবহৃত ধরা হবে &mdash; অর্থাৎ এটি ইতিমধ্যে ব্রিচ। যুক্তি আছে: সমস্যাটি আসলে শুরু থেকেই P1 ছিল, দল শুধু বুঝতে পারেনি।',
            'prio_recompute' => '<strong>Recompute</strong> &mdash; ঘড়ি রিসেট করে টিকিট তৈরির সময় থেকে পূর্বপ্রভাবে নতুন লক্ষ্য প্রয়োগ করা হয়। পরিষ্কার পুনর্গণনা।',
            'prio_reset' => '<strong>Reset</strong> &mdash; অগ্রাধিকার বদলের মুহূর্ত থেকে নতুন ঘড়ি শুরু হয়। দলের জন্য সবচেয়ে সহনশীল, কিন্তু উচ্চ অগ্রাধিকারের টিকিট হঠাৎ নতুন লম্বা ঘড়ি পেলে গ্রাহকরা প্রতারিত বোধ করতে পারেন।',
            'reopen_heading' => 'বন্ধ টিকিট আবার খোলা হলে',
            'reopen_intro' => 'কোনো টিকিট আবার খোলা হলে (বন্ধ হওয়ার পর ব্যবহারকারী উত্তর দিলে):',
            'reopen_reset' => '<strong>Reset (ডিফল্ট)</strong> &mdash; আবার খোলার মুহূর্ত থেকে নতুন রেসপন্স ও রেজোলিউশন ঘড়ি শুরু হয়। আবার খোলাকে কার্যত নতুন টিকিট হিসেবে গণ্য করা হয়।',
            'reopen_continue' => '<strong>Continue</strong> &mdash; বন্ধ হওয়ার সময়ে অতিবাহিত সময় থেকে আবার শুরু হয়। মূল SLA লক্ষ্য প্রযোজ্য থাকে।',
            'first_heading' => 'প্রথম রেসপন্সের সংজ্ঞা',
            'first_intro' => 'কোনটি "প্রথম রেসপন্স" বলে গণ্য হবে &mdash; অর্থাৎ কোন মুহূর্তে রেসপন্স ঘড়ি থামবে?',
            'first_either' => '<strong>Either (ডিফল্ট)</strong> &mdash; যেকোনো ধরনের প্রথম বিশ্লেষক পদক্ষেপ: আউটবাউন্ড ইমেইল, স্ট্যাটাস পরিবর্তন, অ্যাসাইনমেন্ট।',
            'first_status' => '<strong>Status change</strong> &mdash; শুধু ডিফল্ট থেকে অন্য স্ট্যাটাসে পরিবর্তন গণ্য হয়। কঠোরতর &mdash; বিশ্লেষককে সত্যিই টিকিটে কাজ করতে হবে, শুধু ক্লিক করলে হবে না।',
            'first_email' => '<strong>Outbound email</strong> &mdash; শুধু অনুরোধকারীকে ইমেইল উত্তর গণ্য হয়। সবচেয়ে কঠোর &mdash; গ্রাহককে আমাদের কাছ থেকে সাড়া পেতে হবে।',
            'warn_heading' => 'সতর্কতার সীমা শতাংশ',
            'warn_body' => 'SLA লক্ষ্যের কত শতাংশ পার হলে নির্দেশক সবুজ থেকে হলুদ হবে। ডিফল্ট ৮০% &mdash; তাই ৬০ মিনিটের রেসপন্স লক্ষ্যে ৪৮ মিনিট পার হলে হলুদ দেখায়। এটি সতর্কতা-ট্রিগারের ব্রিচ বিজ্ঞপ্তিগুলোও নিয়ন্ত্রণ করে।',
        ],
        'breach' => [
            'heading' => 'ব্রিচ বিজ্ঞপ্তি',
            'sub' => 'বিভাগভিত্তিক কনফিগারযোগ্য ইমেইল নিয়ম, যা SLA ব্রিচের কাছাকাছি এলে (সতর্কতা) বা সত্যিই ব্রিচ হলে চালু হয়।',
            'intro' => 'প্রতিটি নিয়মের চারটি মাত্রা আছে, সবগুলো স্বাধীন:',
            'scope_heading' => '১. পরিধি',
            'scope_body' => 'হয় <strong>Default</strong> (নিয়মটি সব বিভাগের টিকিটে প্রযোজ্য) অথবা একটি <strong>নির্দিষ্ট বিভাগ</strong>। সমাধান: সেই বিভাগের টিকিটের ক্ষেত্রে বিভাগ-নির্দিষ্ট নিয়ম ডিফল্টের ওপর প্রাধান্য পায়। ডিফল্ট নিয়ম না থাকলে, যে বিভাগের নির্দিষ্ট নিয়ম নেই সেটি কোনো বিজ্ঞপ্তি পায় না।',
            'trigger_heading' => '২. ট্রিগার',
            'trigger_body' => 'হয় <strong>Warning</strong> (টিকিট সতর্কতার সীমা পেরিয়েছে &mdash; সম্ভাব্য ব্রিচ) অথবা <strong>Breach</strong> (টিকিট তার লক্ষ্য ছাড়িয়েছে &mdash; প্রকৃত ব্রিচ)। প্রতিটি আলাদা নিয়ম, তাই প্রত্যেকটির জন্য ভিন্ন ভিন্ন মানুষকে জানাতে পারেন।',
            'target_heading' => '৩. লক্ষ্য',
            'target_body' => 'কোন ঘড়ি নজরে রাখা হবে &mdash; <strong>Response</strong>, <strong>Resolution</strong>, অথবা <strong>Both</strong>।',
            'recip_heading' => '৪. প্রাপক',
            'recip_intro' => 'যেকোনো সমন্বয়:',
            'recip_assignee' => '<strong>টিকিটের নিযুক্ত ব্যক্তি</strong> &mdash; বর্তমানে টিকিটের দায়িত্বে থাকা বিশ্লেষক। কেউ নিযুক্ত না থাকলে বাদ যায়।',
            'recip_teams' => '<strong>টিকিটের বিভাগের দলগুলোর সদস্যরা</strong> &mdash; টিকিটের বিভাগের সঙ্গে যুক্ত যেকোনো দলের প্রতিটি বিশ্লেষক। বিতরণ তালিকা না রেখেই পুরো সারিকে কভার করে।',
            'recip_specific' => '<strong>একজন নির্দিষ্ট বিশ্লেষক</strong> &mdash; "SLA champion" / "service manager" ধরনের ব্যবস্থা, যেখানে ভূমিকা নয়, একজন নামধারী ব্যক্তি।',
            'recip_custom' => '<strong>কাস্টম ইমেইল ঠিকানা</strong> &mdash; কমা দিয়ে আলাদা করা মুক্ত লেখা। শেয়ার্ড ইনবক্স (<code>sla-alerts@company.com</code>), Slack/Teams ইমেইল ব্রিজ বা বিতরণ তালিকার জন্য কাজের।',
            'tip' => 'প্রতিটি (লক্ষ্য, ট্রিগার) জোড়ার জন্য একটি টিকিট থেকে সর্বোচ্চ একটি ইমেইল যায় &mdash; কী পাঠানো হয়েছে তা cron ওয়ার্কার <code>sla_notifications_sent</code> টেবিলে ট্র্যাক করে। তাই সতর্কতা একবার যায়, ব্রিচ একবার যায়, ব্যস &mdash; কোনো স্প্যাম লুপ নেই।',
            'warn' => '<strong>নিয়ম নেই = ইমেইল নেই।</strong> সিস্টেমের প্রতিটি টিকিট ব্রিচ করলেও কমপক্ষে একটি নিয়ম যোগ না করা পর্যন্ত কিছুই যাবে না। সবকিছুর কভারেজ পেতে Default-পরিধির একটি Warning + Breach জোড়া দিয়ে শুরু করুন।',
        ],
        'cron' => [
            'heading' => 'Cron জব সেটআপ করা',
            'sub' => 'ব্রিচ-চেক স্ক্রিপ্টটি একটি সময়সূচিতে চালাতে হবে। প্রতি ৫ মিনিটে একবার সবচেয়ে ভালো।',
            'p1' => 'UI-তে দেখা SLA নির্দেশক (ইনবক্সের পিল, রিডিং প্যানের প্যানেল) পেজ লোডের সময় তাৎক্ষণিক হিসাব হয়। কিন্তু কেউ না দেখলেও <em>কোনো কিছু</em> সক্রিয়ভাবে টিকিট পরীক্ষা না করলে ব্রিচ ইমেইল যেতে পারে না। সেই কিছুটি একটি নির্ধারিত টাস্ক &mdash; Windows-এ Task Scheduler, Linux-এ cron।',
            'p2' => 'স্ক্রিপ্টটি FreeITSM ইনস্টল ডিরেক্টরির <code>cron/sla_breach_check.php</code>। এটি দুইভাবে চালানো যায়:',
            'cli_heading' => 'ক. CLI (আপনার নিয়ন্ত্রিত সার্ভারে প্রস্তাবিত)',
            'cli_note' => 'কোনো প্রমাণীকরণ লাগে না &mdash; কে চালাতে পারবে তা ফাইলসিস্টেমের অনুমতিই নিয়ন্ত্রণ করে।',
            'http_heading' => 'খ. HTTP (শেয়ার্ড হোস্টিং বা দূরবর্তী শিডিউলারের জন্য)',
            'http_note' => 'টোকেনটি প্রথম ইনস্টলে স্বয়ংক্রিয়ভাবে তৈরি হয় এবং <code>system_settings</code>-এ <code>sla_cron_token</code> কী-এর অধীনে সংরক্ষিত থাকে (৩২টি হেক্স অক্ষর, ~১২৮ বিট এনট্রপি)। এটি সংরক্ষণকালে এনক্রিপ্ট করা থাকে, তাই সরাসরি সারিটি পড়লে টোকেনের বদলে <code>ENC:…</code> পাবেন। আপনারটি খুঁজে পেতে:',
            'win_heading' => 'Windows Task Scheduler',
