            'sec_heading' => 'নিরাপত্তা &mdash; HTTP এন্ডপয়েন্টকে কী সুরক্ষা দেয়',
            'sec_intro' => 'তিনটি স্তর, সবগুলো স্বয়ংক্রিয়ভাবে প্রয়োগ হয়:',
            'sec_token' => '<strong>১. শেয়ার্ড-সিক্রেট টোকেন</strong> &mdash; প্রতি ইনস্টলে ১২৮-বিট র‍্যান্ডম, টাইমিং আক্রমণ ঠেকাতে ধ্রুব-সময়ের তুলনায় মেলানো হয়।',
            'sec_lockout' => '<strong>২. প্রতি IP-তে ব্যর্থ-প্রমাণীকরণ লকআউট</strong> &mdash; একই IP থেকে গত এক ঘণ্টায় ১০টির বেশি ভুল টোকেন চেষ্টা হলে ১ ঘণ্টার 429 লকআউট হয়। fail2ban ছাড়াই ব্রুট-ফোর্স প্রচেষ্টা ঠেকায়।',
            'sec_interval' => '<strong>৩. সফল রানের মধ্যে ন্যূনতম বিরতি</strong> &mdash; <code>sla_cron_min_interval_seconds</code> (ডিফল্ট ৩০ সেকেন্ড)। বৈধ টোকেনের অনুরোধও শেষ সফল রানের পর এর চেয়ে আগে এলে 429 পায়। ভুলবশত দ্বৈত শিডিউল এবং অনিয়ন্ত্রিত লুপ ঠেকায়।',
            'log_heading' => 'কার্যকলাপ লগ',
            'log_body' => 'প্রতিটি আহ্বান (গৃহীত বা প্রত্যাখ্যাত) সময়, ফলাফল, সংখ্যা এবং ক্লায়েন্ট IP সহ <code>sla_cron_runs</code> টেবিলে লগ হয়। SLA সেটিংস ট্যাবের নিচের <strong>Cron Activity</strong> প্যানেলে শেষ ২০টি রান দেখুন &mdash; সময়সূচি ঠিকমতো চলছে কিনা যাচাই করতে এবং ব্যর্থ প্রমাণীকরণ প্রচেষ্টা অডিট করতে কাজে লাগে। <code>sla_cron_log_retention_days</code> (ডিফল্ট ৩০) পরে সারিগুলো স্বয়ংক্রিয়ভাবে মুছে যায়, ফলে টেবিল ছোট থাকে।',
        ],
        'examples' => [
            'heading' => 'কাজের উদাহরণ',
