            'ex1_heading' => 'উদাহরণ ১: টিকিট যুক্তরাজ্যে তোলা হয়েছে, সার্ভিস ডেস্কও যুক্তরাজ্যে',
            'ex1_title' => 'সহজ ক্ষেত্র',
            'ex1_tag' => 'একক টাইমজোন',
            'ex1_setup' => '<strong>সেটআপ:</strong> <em>UK Office</em> নামে একটি বিজনেস ক্যালেন্ডার, টাইমজোন <code>Europe/London</code>, সোম-শুক্র 09:00-17:00, কোনো ছুটি নেই। P2 অগ্রাধিকারে ১ ঘণ্টার রেসপন্স টার্গেট এবং ৪ ঘণ্টার সমাধান টার্গেট আছে, দুটোই <em>UK Office</em> ক্যালেন্ডার অনুযায়ী চলে।',
            'ex1_scenario' => '<strong>পরিস্থিতি:</strong> ব্যবহারকারী <strong>বুধবার যুক্তরাজ্যের সময় 16:30</strong>-এ একটি P2 টিকিট তোলেন।',
            'ex1_timeline' => 'বুধ 16:30 UK &mdash; <strong>টিকিট তৈরি হলো</strong>, রেসপন্স ক্লক চালু হয়।
বুধ 17:00 UK &mdash; অফিস বন্ধ, ক্লক থামে (60 মিনিটের টার্গেটের 30 মিনিট খরচ হয়েছে)।
বৃহ 09:00 UK &mdash; অফিস খোলে, ক্লক আবার চলে।
বৃহ 09:30 UK &mdash; বিশ্লেষক উত্তর দেন। রেসপন্স SLA ঠিক শেষ মুহূর্তে পূরণ হলো (60 মিনিট খরচ, টার্গেট 60 মিনিট)।',
            'ex1_outro' => 'বিশ্লেষক যদি <strong>বৃহস্পতিবার 10:00 UK</strong> পর্যন্ত উত্তর না দিতেন, তাহলে রেসপন্স <strong>30 মিনিটে লঙ্ঘিত হতো</strong> (টার্গেট 60 মিনিটের বিপরীতে 90 মিনিট খরচ &mdash; বুধবার সন্ধ্যার 30 এবং বৃহস্পতিবার সকালের 60)। ১ ঘণ্টার ক্লক শুধু অফিস সময়ে চলে, তবু দিনের শেষে তোলা টিকিট অফিস আবার খুললে রাতের মধ্যেই বেশির ভাগ বরাদ্দ খরচ করে ফেলে &mdash; 09:00-এ আসা বিশ্লেষকের পক্ষে পুরো এক ঘণ্টা আছে ভেবে নেওয়া সহজ, অথচ আসলে মাত্র 30 মিনিট বাকি।',
            'ex2_heading' => 'উদাহরণ ২: টিকিট যুক্তরাজ্যে তোলা হয়েছে, সার্ভিস ডেস্ক এস্তোনিয়ায়',
            'ex2_title' => 'একাধিক টাইমজোনের ক্ষেত্র',
            'ex2_tag' => '"ন্যায্য" ঠিক করার ৩টি উপায়',
            'ex2_setup' => '<strong>সেটআপ:</strong> যুক্তরাজ্যের গ্রাহক (<code>Europe/London</code>, GMT/BST), এস্তোনিয়ার সার্ভিস ডেস্ক (<code>Europe/Tallinn</code>, EET/EEST &mdash; <strong>যুক্তরাজ্যের 2 ঘণ্টা এগিয়ে</strong>)। দুটো ডেস্কই স্থানীয় সময়ে 09:00-17:00 কাজ করে ধরা হয়।',
            'ex2_scenario' => '<strong>পরিস্থিতি:</strong> যুক্তরাজ্যের গ্রাহক <strong>শুক্রবার যুক্তরাজ্যের সময় 16:30</strong>-এ একটি P2 টিকিট তোলেন (= এস্তোনিয়ায় 18:30, এস্তোনিয়ার অফিস বন্ধ হওয়ার পর)। এস্তোনিয়ার বিশ্লেষকের কাজ ধরার পরবর্তী সুযোগ সোমবার এস্তোনিয়ায় 09:00 (= যুক্তরাজ্যে 07:00)। রেসপন্স টার্গেট ১ ঘণ্টা।',
            'ex2_question' => 'SLA কী বলা উচিত? তিনটি যুক্তিসংগত উত্তর আছে, প্রতিটি আলাদা অর্থে ন্যায্য। আপনার সার্ভিস চুক্তিতে কী প্রতিশ্রুতি আছে তার ভিত্তিতে আপনি ঠিক করেন অগ্রাধিকারে কোন ক্যালেন্ডার দেবেন।',
            'optA_label' => 'বিকল্প A &mdash; গ্রাহককেন্দ্রিক',
            'optA_p1' => '<strong>অগ্রাধিকারে <em>UK</em> সময়ের একটি ক্যালেন্ডার ব্যবহার করুন।</strong> বিশ্লেষক কোথায় আছেন তা নির্বিশেষে ক্লক UK 09:00-17:00 অনুযায়ী চলে।',
            'optA_p2' => 'উপরের পরিস্থিতিতে, টিকিট শুক্রবার 16:30 UK-তে তোলা হলে: ক্লক শুক্রবার UK 16:30&ndash;17:00 চলে (30 মিনিট খরচ), রাত ও সপ্তাহান্তে থামে, সোমবার 09:00 UK-তে আবার চলে। এস্তোনিয়ার বিশ্লেষক যদি সোমবার এস্তোনিয়ায় 10:00-এ (= UK 08:00) উত্তর দেন, তাহলে UK ক্যালেন্ডার তখনও থামা (UK অফিস খোলে UK 09:00-এ), তাই বাড়তি কোনো মিনিট যোগ হয় না &mdash; খরচ 30 মিনিটেই থাকে। <strong>30 মিনিটের মার্জিনসহ SLA পূরণ হয়েছে</strong>। UK 09:30-এর (= এস্তোনিয়া 11:30) পরের যেকোনো উত্তর SLA লঙ্ঘন করবে।',
            'optA_p3' => '<em>যার জন্য ন্যায্য:</em> গ্রাহক। তাঁর অভিজ্ঞতা তাঁর কাজের দিনের সাথে মেলে।<br><em>ছাড়:</em> এস্তোনিয়ার বিশ্লেষকদের UK সময় 09:00-17:00 (= এস্তোনিয়া 11:00-19:00) পাওয়া যেতে হবে, ফলে তাঁদের কাজের দিন 2 ঘণ্টা বেড়ে যায়।',
            'optB_label' => 'বিকল্প B &mdash; বিশ্লেষককেন্দ্রিক',
            'optB_p1' => '<strong>অগ্রাধিকারে <em>এস্তোনিয়া</em> সময়ের একটি ক্যালেন্ডার ব্যবহার করুন।</strong> ক্লক এস্তোনিয়ার 09:00-17:00 অনুযায়ী চলে।',
            'optB_p2' => 'একই পরিস্থিতি: টিকিট শুক্রবার এস্তোনিয়ায় 18:30-এ (অফিস বন্ধের পর) তোলা, ক্লক পুরো সপ্তাহান্ত থামা, সোমবার এস্তোনিয়ায় 09:00 (= UK 07:00) থেকে চলতে শুরু করে। বিশ্লেষক যদি সোমবার এস্তোনিয়ায় 09:30-এ (= UK 07:30) সাড়া দেন, তাহলে রেসপন্স SLA-তে 60 মিনিটের টার্গেটের 30 মিনিট খরচ হয়েছে &mdash; <strong>30 মিনিটের মার্জিনসহ পূরণ হয়েছে</strong>। UK-র গ্রাহক শুক্রবার UK 16:30-এ টিকিট তুলে সোমবার UK 07:30-এ উত্তর পেয়েছেন &mdash; তাঁর ঘড়ির সময়ে অপেক্ষা SLA যা বোঝায় তার চেয়ে অনেক বেশি।',
            'optB_p3' => '<em>যার জন্য ন্যায্য:</em> বিশ্লেষকরা। তাঁরা স্বাভাবিক সময়ে কাজ করেন।<br><em>ছাড়:</em> শুক্রবার বিকেলের টিকিটে সোমবার সকাল এস্তোনিয়ার সময় পর্যন্ত সাড়া না মিললেও রিপোর্টে রেসপন্স SLA ১ ঘণ্টা দেখালে UK-র গ্রাহকদের মনে হতে পারে SLA "মিথ্যা বলছে"। আপনার সার্ভিস চুক্তিতে স্পষ্ট করে লিখুন যে SLA সাপোর্ট-ডেস্কের সময় অনুযায়ী চলে।',
            'optC_label' => 'বিকল্প C &mdash; ওভারল্যাপ উইন্ডো (সবচেয়ে কঠোর)',
            'optC_p1' => '<strong>অগ্রাধিকারে এমন একটি ক্যালেন্ডার ব্যবহার করুন যা শুধু সেই সময় ধরে যখন দুটো ডেস্কই খোলা।</strong> UK 09:00-17:00 এস্তোনিয়ার 09:00-17:00-এর (= UK 07:00-15:00) সাথে <strong>UK 09:00-15:00 উইন্ডোতে</strong> মেলে &mdash; কাজের দিনে 6 ঘণ্টা।',
            'optC_p2' => 'একই পরিস্থিতি: টিকিট শুক্রবার UK 16:30-এ তোলা (ওভারল্যাপের বাইরে, কারণ ওভারল্যাপ UK 15:00-এ বন্ধ হয়), ক্লক সপ্তাহান্তে থামা, সোমবার UK 09:00-এ (= এস্তোনিয়া 11:00, ওভারল্যাপ আবার খোলার মুহূর্ত) আবার চলে। এস্তোনিয়ার বিশ্লেষক যদি এস্তোনিয়া 11:30-এ (= UK 09:30) উত্তর দেন, তাহলে রেসপন্স SLA-তে 60 মিনিটের টার্গেটের 30 মিনিট খরচ হয়েছে &mdash; <strong>30 মিনিটের মার্জিনসহ পূরণ হয়েছে</strong>। উত্তরটি ওভারল্যাপ উইন্ডোর মধ্যে হয়েছে, তাই তা সঙ্গে সঙ্গে গণনায় আসে।',
            'optC_p3' => '<em>যার জন্য ন্যায্য:</em> দুই পক্ষই &mdash; SLA শুধু সেই সময়ে চলে যখন ডেস্ক সত্যিই টিকিটে অগ্রগতি করতে পারে এবং গ্রাহকও উত্তর পেতে নিজের ডেস্কে আছেন।<br><em>ছাড়:</em> দৈনিক উইন্ডো ছোট হওয়ায় কঠোর টার্গেট পূরণে ঘড়ির সময় বেশি লাগে। 4 ঘণ্টার সমাধান টার্গেট ওভারল্যাপের দেড় দিন জুড়ে চলে, অথচ স্বাভাবিক 8 ঘণ্টার ক্যালেন্ডারে তা একদিনেই শেষ হতো।',
            'choose_tip' => '<strong>কীভাবে বাছবেন:</strong> আপনার সার্ভিস চুক্তি দেখুন। যদি লেখা থাকে "প্রাপ্তির ১ ঘণ্টার মধ্যে রেসপন্স" &mdash; সেটি বিকল্প A (গ্রাহকের ক্লক)। যদি লেখা থাকে "১ কর্মঘণ্টার মধ্যে রেসপন্স" &mdash; সেটি সাধারণত বিকল্প B (যে ডেস্ক কাজ করছে সেটির)। যদি লেখা থাকে "পারস্পরিক উপস্থিতির ১ ঘণ্টার মধ্যে" &mdash; সেটি বিকল্প C। চুক্তি না থাকলে দলকে জিজ্ঞাসা করুন: আপনারা কি এস্তোনিয়ার সময়ের বাইরেও চাপ অনুভব করতে চান (বিকল্প A), নাকি UK-র গ্রাহকরা মাঝে মাঝে অবহেলিত বোধ করুন (বিকল্প B)?',
            'ex3_heading' => 'উদাহরণ ৩: ভেন্ডরের অপেক্ষার সময় ক্লক থামানো',
            'ex3_title' => 'বাস্তবে পজ স্ট্যাটাস কীভাবে কাজ করে',
            'ex3_tag' => 'ক্লক থামানো',
            'ex3_setup' => '<strong>সেটআপ:</strong> P3 অগ্রাধিকার, 8 কর্মঘণ্টার সমাধান টার্গেট, UK ক্যালেন্ডার, "Awaiting Vendor" স্ট্যাটাসে <em>Pause SLA</em> চিহ্নিত।',
            'ex3_scenario' => '<strong>পরিস্থিতি:</strong> টিকিট সোমবার 09:00 UK-তে তোলা। বিশ্লেষক সোমবার 11:00 UK-তে Microsoft-এর কাছে এস্কেলেট করেন এবং টিকিট "Awaiting Vendor"-এ সরান। Microsoft বুধবার 14:00 UK-তে উত্তর দেয়। বিশ্লেষক সমাধান প্রয়োগ করে বৃহস্পতিবার 10:00 UK-তে বন্ধ করেন।',
            'ex3_timeline' => 'সোম 09:00 &mdash; টিকিট তৈরি, সমাধান ক্লক চলছে।
সোম 11:00 &mdash; "Awaiting Vendor"-এ সরানো হলো, <strong>ক্লক থামল</strong> (2 ঘণ্টা খরচ)।
বুধ 14:00 &mdash; "In Progress"-এ ফিরিয়ে আনা হলো, <strong>ক্লক আবার চলল</strong>।
বুধ 17:00 &mdash; অফিস বন্ধ (মোট 5 ঘণ্টা খরচ)।
